232	    /**
233	     * Open a claim's editor: the claim is locked for every other user until the editor is saved or
234	     * cancelled, or the sheet's today changes. Refused (403) for a viewer, (409) for a claim that is
235	     * not DRAFT or is locked by another user, and (423) when dated inside a closed period; a refused
236	     * claim takes no lock. Any other claim of the same person the user had locked is released.
237	     */
238	    @Transactional
239	    public Claim lock(String sheetId, String user, long id) {
240	        roles.refuseViewer(sheetId, user);
241	        // hold the sheet so two users cannot both take the lock
242	        sheets.lock(sheetId);
243	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
244	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
245	        refuseIfNotEditable(sheetId, user, claim);
246	        periods.refuseIfClosed(sheetId, claim.getDueBy());
247	        for (Claim other : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())) {
248	            if (other.getId() != id && user.equals(other.getLockedBy())) {
249	                other.setLockedBy(null);
250	                claims.save(other);
251	            }
252	        }
253	        claim.setLockedBy(user);
254	        return claims.saveAndFlush(claim);
255	    }
