320	    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
321	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
322	            boolean review, String voidReason) {
323	        roles.refuseViewer(sheetId, user);
324	        if (!review) {
325	            roles.refuseUnlessPermitted(sheetId, user, switch (next) {
326	                case OPEN -> "open";
327	                case SETTLED -> "settle";
328	                case VOID -> "void";
329	                default -> throw new IllegalStateException();
330	            });
331	        }
332	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
333	        if (next == ClaimStatus.OPEN) {
334	            sheets.lock(sheetId);
335	        }
336	        RollupService.Snapshot before = rollup.snapshot(sheetId);
337	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
338	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
339	        ClaimStatus was = claim.getStatus();
340	        // only a steward's review moves a PENDING claim on, other than voiding it
341	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
342	            throw new ResponseStatusException(HttpStatus.CONFLICT,
343	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
344	        }
345	        periods.refuseIfClosed(sheetId, claim.getDueBy());
346	        boolean reversing = was == ClaimStatus.SETTLED;
347	        if (reversing) {
348	            refuseVoidSettled(sheetId, user, claim);
349	        }
350	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
351	            throw new ResponseStatusException(HttpStatus.CONFLICT,
352	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
353	        }
354	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
355	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
356	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
357	        }
358	        if (next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
359	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
360	                    "The user who last edited a claim cannot " + (review ? "approve" : "settle") + " it.");
361	        }
362	        if (review && !isSteward(sheetId, user)) {
363	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
364	                    "Only a steward can approve or reject a PENDING claim.");
365	        }
366	        String voidedWith = next == ClaimStatus.VOID ? voidReasons.refuseUnlessListed(sheetId, voidReason) : null;
367	        Person person = person(sheetId, claim.getPersonId());
368	        if (next == ClaimStatus.OPEN && !review && needsNote(sheetId, person, claim)) {
369	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
370	                    "A claim due above the note threshold cannot be opened with an empty note.");
371	        }
372	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
373	        // PENDING claim's figure is live)
374	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
375	        if (next == ClaimStatus.SETTLED && needsProof(sheetId, person, claim, settling)) {
376	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
377	                    "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
378	                            + " without a proof.");
379	        }
380	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
381	            next = ClaimStatus.PENDING;
382	            settling = null;
383	        }
384	        claim.setStatus(next);
385	        if (next == ClaimStatus.OPEN && !review) {
386	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
387	            claim.setOpenedBy(user);
388	        } else if (next == ClaimStatus.SETTLED) {
389	            claim.setSettledDue(settling);
390	        } else if (next == ClaimStatus.VOID) {
391	            claim.setVoidReason(voidedWith);
392	        }
393	        logStatus(sheetId, user, person, claim);
394	        Claim saved = claims.saveAndFlush(claim);
395	        String event = switch (next) {
396	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
397	            case PENDING -> "CLAIM_PENDING";
398	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
399	            case VOID -> "CLAIM_VOIDED";
400	            case DRAFT -> throw new IllegalStateException();
401	        };
402	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
403	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
404	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
405	                + (reason != null ? " reason=" + reason : "")
406	                + (reversing ? " reversed=" + dueText(saved.getSettledDue()) : "")
407	                + (voidedWith != null ? " reason=" + voidedWith : ""));
408	        if (next == ClaimStatus.SETTLED) {
409	            notifyWatchers(sheetId, user, person, saved);
410	        }
411	        rollup.recordChanges(sheetId, user, before);
412	        return saved;
413	    }
