415	    /**
416	     * Refuse voiding a SETTLED claim: (403) for anyone but a steward, and (409) once the sheet's
417	     * today is more than {@value #VOID_SETTLED_DAYS} days after its settlement (or before it).
418	     */
419	    private void refuseVoidSettled(String sheetId, String user, Claim claim) {
420	        if (!isSteward(sheetId, user)) {
421	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a SETTLED claim.");
422	        }
423	        LocalDate settled = claim.getLog().stream().filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
424	                .map(ClaimLogEntry::getDate).reduce((first, last) -> last).orElse(null);
425	        LocalDate today = sheets.today(sheetId);
426	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
427	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can be voided only within "
428	                    + VOID_SETTLED_DAYS + " days of its settlement.");
429	        }
430	    }
