618	    private Claim reassign(String sheetId, String user, long id, long toPersonId, boolean allowSamePerson) {
619	        roles.refuseUnlessPermitted(sheetId, user, "reassign");
620	        RollupService.Snapshot before = rollup.snapshot(sheetId);
621	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
622	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
623	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
624	            throw new ResponseStatusException(HttpStatus.CONFLICT,
625	                    "A " + claim.getStatus() + " claim cannot be moved.");
626	        }
627	        Person from = person(sheetId, claim.getPersonId());
628	        Person to = person(sheetId, toPersonId);
629	        if (!allowSamePerson && from.getId().equals(to.getId())) {
630	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
631	        }
632	        if (claim.isCorrection()) {
633	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
634	        }
635	        periods.refuseIfClosed(sheetId, claim.getDueBy());
636	        refuseIfRetired(to, claim.getDate());
637	        claim.setPersonId(to.getId());
638	        claim.bind(false, null);
639	        claims.saveAndFlush(claim);
640	        claims.listFirst(claim.getId());
641	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
642	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
643	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
644	                + " from=" + from.getName() + " to=" + to.getName());
645	        rollup.recordChanges(sheetId, user, before);
646	        return saved;
647	    }
648	
649	    /** What a split did: the original claim, keeping the rest of its amount, and the new claim split off it. */
650	    public record Split(Claim original, Claim split) {
651	    }
652	
653	    /**
654	     * Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from
655	     * any statement; a new OPEN claim with the amount split off, the same date and note, the next
656	     * number, opened by the user and due by its date plus the terms in force on it, is listed first
657	     * under the person and shows the original's number as split-from. Refused (403) for a role that
658	     * may not open a claim, (409) for a claim that is not OPEN or is deferred, (400) for an amount
659	     * not above 0.00 and below the claim's, and (423) when the original is due inside a closed period
660	     * (the split's own due-by is not checked). The split is numbered in, and a late entry of, the
661	     * period of its own due-by.
662	     */
663	    @Transactional
664	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
665	        roles.refuseViewer(sheetId, user);
666	        roles.refuseUnlessPermitted(sheetId, user, "open");
667	        // lock the sheet's numbering before reading the claim, as opening one does
668	        sheets.lock(sheetId);
669	        RollupService.Snapshot before = rollup.snapshot(sheetId);
670	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
671	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
672	        if (claim.getStatus() != ClaimStatus.OPEN) {
673	            throw new ResponseStatusException(HttpStatus.CONFLICT,
674	                    "A " + claim.getStatus() + " claim cannot be split.");
675	        }
676	        if (claim.isDeferredOn(sheets.today(sheetId))) {
677	            throw new ResponseStatusException(HttpStatus.CONFLICT,
678	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then.");
679	        }
680	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
681	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
682	                    "A split must be more than 0.00 and less than the claim's amount.");
683	        }
684	        periods.refuseIfClosed(sheetId, claim.getDueBy());
685	        Person person = person(sheetId, claim.getPersonId());
686	        claim.setAmount(claim.getAmount().subtract(amount));
687	        claim.bind(false, null);
688	        Claim original = claims.saveAndFlush(claim);
689	        LocalDate dated = claim.getDate();
690	        int terms = terms(sheetId, person, dated);
691	        Claim split = new Claim(sheetId, person.getId(), amount, dated, dueBy(sheetId, dated, terms), terms,
692	                claim.getNote(), null);
693	        split.setStatus(ClaimStatus.OPEN);
694	        split.setNumber(sheets.nextClaimNumber(sheetId, split.getDueBy()));
695	        split.setLateEntry(periods.isSoftClosed(sheetId, split.getDueBy()));
696	        split.setOpenedBy(user);
697	        split.setSplitFrom(original.getNumber());
698	        split.setTags(original.getTags());
699	        logStatus(sheetId, user, person, split);
700	        Claim added = claims.saveAndFlush(split);
701	        audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original)
702	                + " number=" + original.getNumber() + " into=" + added.getNumber());
703	        audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, added) + " number=" + added.getNumber());
704	        rollup.recordChanges(sheetId, user, before);
705	        return new Split(original, added);
706	    }
707	
708	    /** What a bulk open did: how many claims were opened and how many refused, and the claims opened. */
709	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
710	    }
711	
712	    /**
713	     * Open the given claims together, in list order (the order people were added, newest claim
714	     * first within a person), so they are numbered in that order. A claim that cannot be opened
715	     * (not on the sheet, not DRAFT, dated inside a closed period, or due above the note threshold
716	     * with an empty note) is refused and left as it is.
717	     */
718	    @Transactional
719	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
720	        List<Claim> selected = inListOrder(sheetId, ids);
721	        int refused = (int) ids.stream().distinct().count() - selected.size();
722	        List<Claim> opened = new ArrayList<>();
723	        boolean permitted = sheets.sheet(sheetId).permits("open", roles.roleOf(sheetId, user));
724	        for (Claim claim : selected) {
725	            if (!permitted || claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDueBy())
726	                    || needsNote(sheetId, person(sheetId, claim.getPersonId()), claim)) {
727	                refused++;
728	                continue;
729	            }
730	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
731	        }
732	        return new BulkOpened(opened.size(), refused, opened);
733	    }
734	
735	    /**
736	     * What a bulk settle did: how many claims were settled (or made PENDING) and how many refused,
737	     * the claims changed, and the sheet's last batch number after it (0 when there has been none).
738	     */
739	    public record BulkSettled(int settled, int refused, List<Claim> claims, int lastBatch) {
740	    }
741	
742	    /**
743	     * Settle the given claims together, all or nothing: in list order (the order people were added,
744	     * newest claim first within a person), each by exactly the rules of settling one claim. A claim
745	     * a clerk's settle makes PENDING counts as settled. When any selected claim cannot be settled
746	     * (or is not on the sheet), none is: every one counts as refused and nothing is written. Else the
747	     * settle is a batch: it takes the sheet's next batch number, each claim is marked with it, and
748	     * after the claims' own records one BATCH_SETTLED record gives the batch, its count and the
749	     * frozen dues of those SETTLED added up.
750	     */
751	    @Transactional
752	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
753	        List<Claim> selected = inListOrder(sheetId, ids);
754	        int requested = (int) ids.stream().distinct().count();
755	        List<Claim> settled = new ArrayList<>();
756	        boolean refusedAny = selected.size() < requested;
757	        for (Claim claim : selected) {
758	            if (refusedAny) {
759	                break;
760	            }
761	            try {
762	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
763	            } catch (ResponseStatusException refusedOne) {
764	                refusedAny = true;
765	            }
766	        }
767	        if (refusedAny || settled.isEmpty()) {
768	            // undo the claims already settled, and the records waiting for the commit with them
769	            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
770	            return new BulkSettled(0, requested, List.of(), sheets.sheet(sheetId).getLastBatch());
771	        }
772	        int batch = sheets.nextBatch(sheetId);
773	        List<Claim> batched = new ArrayList<>();
774	        BigDecimal total = BigDecimal.ZERO;
775	        for (Claim claim : settled) {
776	            claim.setBatch(batch);
777	            batched.add(claims.saveAndFlush(claim));
778	            if (claim.getStatus() == ClaimStatus.SETTLED) {
779	                total = total.add(claim.getSettledDue());
780	            }
781	        }
782	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
783	                + " count=" + batched.size() + " total=" + dueText(total));
784	        return new BulkSettled(batched.size(), 0, batched, batch);
785	    }
786	
787	    /** What a bulk move did: how many claims were moved and how many refused, and the claims moved. */
788	    public record BulkReassigned(int reassigned, int refused, List<Claim> claims) {
789	    }
790	
791	    /**
792	     * Move the given claims to one person together, in list order (the order people were added,
793	     * newest claim first within a person), each by exactly the rules of moving one claim. A claim
794	     * already on that person is moved in place (listed first, unbound). A claim that cannot be
795	     * moved is refused and left as it is.
796	     */
797	    @Transactional
798	    public BulkReassigned bulkReassign(String sheetId, String user, Collection<Long> ids, long toPersonId) {
799	        List<Claim> selected = inListOrder(sheetId, ids);
800	        int refused = (int) ids.stream().distinct().count() - selected.size();
801	        List<Claim> moved = new ArrayList<>();
802	        for (Claim claim : selected) {
803	            try {
804	                moved.add(reassign(sheetId, user, claim.getId(), toPersonId, true));
805	            } catch (ResponseStatusException refusedOne) {
806	                // every refusal is checked before the claim is changed, so it is left as it is
807	                refused++;
808	            }
809	        }
810	        return new BulkReassigned(moved.size(), refused, moved);
811	    }
812	
813	    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
814	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
815	        Map<Long, Integer> personOrder = new HashMap<>();
816	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
817	        for (int i = 0; i < listed.size(); i++) {
818	            personOrder.put(listed.get(i).getId(), i);
819	        }
820	        return ids.stream().distinct()
821	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
822	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
823	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
824	                .toList();
825	    }
826	
827	    /**
828	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
829	     * rounded to the cent as the claim rounds (see {@link Rounding}), not raised to the floor (see {@link LateCharge});
830	     * null with no rate in force then.
831	     */
832	    public BigDecimal due(String sheetId, Person person, Claim claim) {
833	        Sheet sheet = sheets.sheet(sheetId);
834	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
835	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
836	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
837	                .orElse(null);
838	    }
839	
840	    /** What a candidate rate would change: how many claims would show a different due, and the sum of new minus current. */
841	    public record RatePreview(int count, BigDecimal diff) {
842	    }
843	
844	    /**
845	     * Preview a candidate rate for a grade, as if it applied to that grade on every date: of the
846	     * OPEN and PENDING claims whose person has the grade on the claim's date, how many would show a
847	     * different due and the sum of the differences (new due minus current due). A claim bound by a
848	     * statement keeps its figure; a claim with no due counts as 0.00. Nothing is saved.
849	     */
850	    @Transactional(readOnly = true)
851	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
852	        Sheet sheet = sheets.sheet(sheetId);
853	        Map<Long, Person> byId = new HashMap<>();
854	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
855	            byId.put(p.getId(), p);
856	        }
857	        int count = 0;
858	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
859	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
860	            Person person = byId.get(claim.getPersonId());
861	            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) {
862	                continue;
863	            }
864	            if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) {
865	                continue;
866	            }
867	            BigDecimal current = charged(sheetId, person, claim);
868	            RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
869	            BigDecimal figure = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding);
870	            BigDecimal next = LateCharge.withCharge(sheet, claim, grade, figure);
871	            BigDecimal was = current == null ? BigDecimal.ZERO : current;
872	            if (current == null || was.compareTo(next) != 0) {
873	                count++;
874	                diff = diff.add(next.subtract(was));
875	            }
876	        }
877	        return new RatePreview(count, diff.setScale(2, RoundingMode.UNNECESSARY));
878	    }
879	
880	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
881	    private LocalDate roundingDate(String sheetId, Claim claim) {
882	        if (!claim.isCorrection() || claim.getCorrects() == null) {
883	            return claim.getDate();
884	        }
885	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
886	    }
887	
888	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
889	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
890	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
891	                dueText(charged(sheetId, person, claim))));
892	    }
893	
894	    private static String dueText(BigDecimal due) {
895	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
896	    }
897	
898	    /**
899	     * Whether a claim settling at the figure is above the proof threshold in force on its date (its
900	     * person's grade's then when it has one, else the sheet's) and has no proofs.
901	     */
902	    private boolean needsProof(String sheetId, Person person, Claim claim, BigDecimal figure) {
903	        BigDecimal threshold = sheets.sheet(sheetId).proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
904	        return claim.getProofs() == 0 && figure != null && threshold != null && figure.compareTo(threshold) > 0;
905	    }
906	
907	    /** Whether a claim's due is above the note threshold in force on its date and its note is empty. */
908	    private boolean needsNote(String sheetId, Person person, Claim claim) {
909	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
910	            return false;
911	        }
912	        BigDecimal threshold = sheets.sheet(sheetId).noteThresholdOn(claim.getDate());
913	        BigDecimal due = threshold == null ? null : charged(sheetId, person, claim);
914	        return due != null && due.compareTo(threshold) > 0;
915	    }
916	
917	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
918	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
919	        BigDecimal limit = sheets.clerkLimit(sheetId);
920	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
921	    }
922	
923	    private boolean isSteward(String sheetId, String user) {
924	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
925	    }
926	
927	    /**
928	     * The number a claim corrects: none unless its amount is negative, when it must name the number
929	     * of a SETTLED claim of the same person, else it is refused (400).
930	     */
931	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
932	        if (amount.signum() >= 0) {
933	            return null;
934	        }
935	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
936	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
937	        if (!settled) {
938	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
939	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
940	        }
941	        return corrects;
942	    }
943	
944	    /** Refuse (422) a claim dated after its person's retirement date. */
945	    private static void refuseIfRetired(Person person, LocalDate date) {
946	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
947	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
948	                    "That claim's date is after its person's retirement date.");
949	        }
950	    }
951	
952	    private Person person(String sheetId, long personId) {
953	        return people.findByIdAndSheetId(personId, sheetId)
954	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
955	    }
956	
957	    /** Refuse a reference (none when null) another claim on the sheet already has, without regard to case. */
958	    void refuseIfRefUsed(String sheetId, String ref, Long exceptId) {
959	        if (ref != null && (exceptId == null ? claims.existsBySheetIdAndRefIgnoreCase(sheetId, ref)
960	                : claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, ref, exceptId))) {
961	            throw new ResponseStatusException(HttpStatus.CONFLICT,
962	                    "The reference " + ref + " is already used on this sheet.");
963	        }
964	    }
965	
966	    /** Every tag ever used on the sheet, sorted. */
967	    @Transactional(readOnly = true)
968	    public List<String> usedTags(String sheetId) {
969	        return usedTags.findBySheetIdOrderByTagAsc(sheetId).stream().map(UsedTag::getTag).toList();
970	    }
971	
972	    /** Keep each of the claim's tags as used on the sheet. */
973	    private void useTags(String sheetId, Claim claim) {
974	        for (String tag : claim.getTags()) {
975	            if (!usedTags.existsBySheetIdAndTag(sheetId, tag)) {
976	                usedTags.saveAndFlush(new UsedTag(sheetId, tag));
977	            }
978	        }
979	    }
980	
981	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
982	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
983	                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
984	    }
985	
986	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
987	        return date != null ? date : sheets.entryDate(sheetId);
988	    }
989	}
