327	    /** The grades recorded, the first from the beginning of time (no from-date), the others each from a date. */
328	    @ElementCollection(fetch = FetchType.EAGER)
329	    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
330	    private List<DatedGrade> grades = new ArrayList<>();
