340	    /** Set once retired: the person counts as retired at once, whatever the date. */
341	    @Column(name = "retired_from")
342	    private LocalDate retiredFrom;
343	
344	    /** The sheet's today when the person was retired; none while not retired. */
345	    @Column(name = "retired_on")
346	    private LocalDate retiredOn;
347	
348	    /** The sheet's today when the person was added; none for one added before it was recorded. */
349	    @Column(name = "added_on")
350	    private LocalDate addedOn;
