352	    /** The person's OPEN claims dated within a hold, and not bound by a statement, count in no live total. */
353	    @ElementCollection(fetch = FetchType.EAGER)
354	    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
355	    private List<DatedHold> holds = new ArrayList<>();
