408	     */
409	    public String gradeOn(LocalDate date, LocalDate asOf) {
410	        String found = null;
411	        for (DatedGrade g : getGrades()) {
412	            if (g.madeBy(asOf) && (g.getFromDate() == null || !g.getFromDate().isAfter(date))) {
