468	    /** The holds recorded, by from-date. */
469	    public List<DatedHold> getHolds() {
470	        return holds.stream().sorted(Comparator.comparing(DatedHold::getFromDate)
471	                .thenComparing(DatedHold::getToDate, Comparator.nullsLast(Comparator.naturalOrder()))).toList();
472	    }
