474	    /** Add a hold; {@code madeOn} is the sheet's today. */
475	    public void addHold(LocalDate fromDate, LocalDate toDate, LocalDate madeOn) {
476	        holds.add(new DatedHold(fromDate, toDate, madeOn));
477	    }
