479	    /** Whether the person has any hold. */
480	    public boolean isHeld() {
481	        return !holds.isEmpty();
482	    }
483	
484	    /** Whether a day lies within one of the person's holds. */
485	    public boolean heldOn(LocalDate date) {
486	        return holds.stream().anyMatch(h -> h.covers(date));
487	    }
