489	    /**
490	     * Whether a claim of this person counts toward the live totals: an open claim dated within a
491	     * hold does not, nor does one of a person whose retirement date the sheet's today has reached,
492	     * unless a statement binds it; nor does a claim deferred on the sheet's today.
493	     */
494	    public boolean counts(Claim claim, LocalDate today) {
495	        return counts(claim, claim.getStatus(), today);
496	    }
497	
498	    /**
499	     * Whether a claim of this person counts by the same rules, had it the given status; a hold or a
500	     * reached retirement takes out only a claim that is open now as well (one since settled or voided is not).
501	     */
502	    public boolean counts(Claim claim, ClaimStatus status, LocalDate today) {
503	        return status.counts() && !claim.isDeferredOn(status, today) && (claim.isStated()
504	                || !(status.isOpen() && claim.getStatus().isOpen() && (heldOn(claim.getDate()) || retiredOn(today))));
505	    }
506	
507	    /**
508	     * Whether a claim of this person counted at the end of a day, as the person stood then: had it
509	     * the given status then, and was it bound by a statement then ({@code stated}). The day stands in
510	     * for the sheet's today, and only holds and a retirement recorded while the sheet's today was on
511	     * or before it count.
512	     */
513	    public boolean countedAsOf(Claim claim, ClaimStatus status, LocalDate day, boolean stated) {
514	        boolean held = holds.stream().anyMatch(h -> h.madeBy(day) && h.covers(claim.getDate()));
515	        boolean retired = retiredFrom != null && (retiredOn == null || !retiredOn.isAfter(day))
516	                && !day.isBefore(retiredFrom);
517	        return status.counts() && !claim.isDeferredAsOf(status, day)
518	                && (stated || !(status.isOpen() && (held || retired)));
519	    }
