528	/**
529	 * The people on a sheet: listed in the order they were added, added and edited by name and grade. A
530	 * person's grade is dated: the first applies from the beginning of time, and each edit records the
531	 * grade from its from-date (the sheet's today when none is given), keeping those already recorded;
532	 * an edit leaving the grade in force on the sheet's today as it is, with no from-date, records none.
533	 * A
534	 * name is unique on the sheet, compared without regard to case (names arrive trimmed). A person can
535	 * be retired from a date (the sheet's today when none is given); they count as retired at once. A
536	 * person can be put on hold over a span of dates, and may have several holds over time. A person can name other people on the sheet as
537	 * their patrons, one at a time: not themselves, and not the same person twice. A user can watch a
538	 * person, and stop watching them; each user's watching is their own. A person may have their own
539	 * terms, in days; a claim's due-by takes them before the terms of the person's grade and the sheet's.
540	 * A person may have a contact (arriving trimmed and lower-cased, null for none), unique on the sheet.
541	 */
542	@Service
543	public class PersonService {
544	
545	    private final PersonRepository people;
546	    private final SheetService sheets;
547	    private final Audit audit;
548	    private final RollupService rollup;
549	    private final PatronRepository patrons;
550	    private final RoleService roles;
551	    private final WatchRepository watches;
552	
553	    public PersonService(PersonRepository people, SheetService sheets, Audit audit, RollupService rollup,
554	            PatronRepository patrons, RoleService roles, WatchRepository watches) {
555	        this.roles = roles;
556	        this.watches = watches;
557	        this.people = people;
558	        this.patrons = patrons;
559	        this.sheets = sheets;
560	        this.audit = audit;
561	        this.rollup = rollup;
562	    }
563	
564	    @Transactional(readOnly = true)
565	    public List<Person> list(String sheetId) {
566	        return people.findBySheetIdOrderByIdAsc(sheetId);
567	    }
568	
569	    @Transactional
570	    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
571	        return add(sheetId, user, name, grade, terms, null);
572	    }
573	
574	    @Transactional
575	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
576	        roles.refuseViewer(sheetId, user);
577	        sheets.load(sheetId, user);
578	        RollupService.Snapshot before = rollup.snapshot(sheetId);
579	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
580	            throw nameInUse();
581	        }
582	        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
583	            throw contactInUse();
584	        }
585	        Person person = new Person(sheetId, name, grade, sheets.today(sheetId));
586	        person.setTerms(terms);
587	        person.setContact(contact);
588	        Person added = save(person);
589	        audit.recordOnCommit(record("PERSON_ADDED", sheetId, user, added, sheets.today(sheetId))
590	                + (terms != null ? " terms=" + terms : "") + (contact != null ? " contact=" + contact : ""));
591	        rollup.recordChanges(sheetId, user, before);
592	        return added;
593	    }
594	
595	    @Transactional
596	    public Person update(String sheetId, String user, long id, long version, String name, String grade,
597	            LocalDate gradeFrom, Integer terms, String contact) {
598	        roles.refuseViewer(sheetId, user);
599	        RollupService.Snapshot before = rollup.snapshot(sheetId);
600	        Person person = people.findByIdAndSheetId(id, sheetId)
601	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
602	        if (person.getVersion() != version) {
603	            throw stale();
604	        }
605	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, name, id)) {
606	            throw nameInUse();
607	        }
608	        if (contact != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contact, id)) {
609	            throw contactInUse();
610	        }
611	        LocalDate today = sheets.today(sheetId);
612	        Integer termsBefore = person.getTerms();
613	        String contactBefore = person.getContact();
614	        person.setName(name);
615	        person.setTerms(terms);
616	        person.setContact(contact);
617	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
618	            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade, today);
619	        }
620	        Person saved = save(person);
621	        audit.recordOnCommit(record("PERSON_EDITED", sheetId, user, saved, today)
622	                + (Objects.equals(termsBefore, terms) ? "" : " terms=" + (terms != null ? terms : ""))
623	                + (Objects.equals(contactBefore, contact) ? "" : " contact=" + (contact != null ? contact : "")));
624	        rollup.recordChanges(sheetId, user, before);
625	        return saved;
626	    }
627	
628	    /**
629	     * Give each of the people a grade from a from-date (the sheet's today when none is given), in list
630	     * order, exactly as editing each with the person form would (name, terms and contact kept). All or none: a
631	     * person not on the sheet refuses the lot. A viewer may grade no one: each person is refused and
632	     * none is graded.
633	     */
634	    @Transactional
635	    public List<Person> bulkGrade(String sheetId, String user, List<Long> ids, String grade, LocalDate gradeFrom) {
636	        try {
637	            roles.refuseViewer(sheetId, user);
638	        } catch (ResponseStatusException e) {
639	            if (e.getStatusCode() == HttpStatus.FORBIDDEN) {
640	                return List.of();
641	            }
642	            throw e;
643	        }
644	        Set<Long> wanted = new HashSet<>(ids);
645	        List<Person> chosen = people.findBySheetIdOrderByIdAsc(sheetId).stream()
646	                .filter(p -> wanted.contains(p.getId())).toList();
647	        if (chosen.size() != wanted.size()) {
648	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet.");
649	        }
650	        return chosen.stream().map(p -> update(sheetId, user, p.getId(), p.getVersion(), p.getName(), grade,
651	                gradeFrom, p.getTerms(), p.getContact())).toList();
652	    }
653	
654	    /**
655	     * Retire the person from a date, or from the sheet's today when none is given. Once the sheet's
656	     * today reaches that date their OPEN claims leave every live total, so the figures that move are recorded.
657	     */
658	    @Transactional
659	    public Person retire(String sheetId, String user, long id, LocalDate date) {
660	        roles.refuseViewer(sheetId, user);
661	        Person person = people.findByIdAndSheetId(id, sheetId)
662	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
663	        RollupService.Snapshot before = rollup.snapshot(sheetId);
664	        LocalDate from = date != null ? date : sheets.today(sheetId);
665	        person.setRetiredFrom(from, sheets.today(sheetId));
666	        Person saved = save(person);
667	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName() + " from="
668	                + from);
669	        rollup.recordChanges(sheetId, user, before);
670	        return saved;
671	    }
672	
673	    /**
674	     * Put the person on hold from a date (the sheet's today when none is given) to an optional
675	     * to-date; refused (400) when the to-date is before the from-date. Their OPEN claims dated within
676	     * the hold leave every live total, so the figures that move are recorded.
677	     */
678	    @Transactional
679	    public Person hold(String sheetId, String user, long id, LocalDate fromDate, LocalDate toDate) {
680	        roles.refuseViewer(sheetId, user);
681	        RollupService.Snapshot before = rollup.snapshot(sheetId);
682	        Person person = people.lockByIdAndSheetId(id, sheetId)
683	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
684	        LocalDate from = fromDate != null ? fromDate : sheets.today(sheetId);
685	        if (toDate != null && toDate.isBefore(from)) {
686	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
687	        }
688	        person.addHold(from, toDate, sheets.today(sheetId));
689	        Person saved = save(person);
690	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName() + " from="
691	                + from);
692	        rollup.recordChanges(sheetId, user, before);
693	        return saved;
694	    }
695	
696	    @Transactional(readOnly = true)
697	    public List<Patron> patrons(String sheetId) {
698	        return patrons.findBySheetIdOrderByIdAsc(sheetId);
699	    }
700	
701	    /**
702	     * Name another person on the sheet as the person's patron; refused (409) when it is the person
703	     * themselves or already one of their patrons.
704	     */
705	    @Transactional
706	    public Patron addPatron(String sheetId, String user, long id, long patronId) {
707	        roles.refuseViewer(sheetId, user);
708	        Person person = people.findByIdAndSheetId(id, sheetId)
709	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
710	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
711	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet."));
712	        if (person.getId().equals(patron.getId())) {
713	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
714	        }
715	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
716	            throw patronTaken();
717	        }
718	        Patron added;
719	        try {
720	            added = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
721	        } catch (DataIntegrityViolationException e) {
722	            throw patronTaken();
723	        }
724	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
725	                + " patron=" + patron.getName());
726	        return added;
727	    }
728	
729	    /** The ids of the people the user watches on the sheet. */
730	    @Transactional(readOnly = true)
731	    public List<Long> watched(String sheetId, String user) {
732	        return watches.findBySheetIdAndUserName(sheetId, user).stream().map(Watch::getPersonId).toList();
733	    }
734	
735	    /**
736	     * Start ({@code on}) or stop watching the person as the user; already so, nothing changes and
737	     * nothing is recorded.
738	     */
739	    @Transactional
740	    public void watch(String sheetId, String user, long id, boolean on) {
741	        roles.refuseViewer(sheetId, user);
742	        sheets.refuseIfArchived(sheetId);
743	        Person person = people.lockByIdAndSheetId(id, sheetId)
744	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
745	        var existing = watches.findByPersonIdAndUserName(person.getId(), user);
746	        if (on == existing.isPresent()) {
747	            return;
748	        }
749	        if (on) {
750	            watches.saveAndFlush(new Watch(sheetId, person.getId(), user));
751	        } else {
752	            watches.delete(existing.get());
753	            watches.flush();
754	        }
755	        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
756	                + " name=" + person.getName());
757	    }
758	
759	    private static ResponseStatusException patronTaken() {
760	        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron.");
761	    }
762	
763	    /** A person's record, with the grade in force on the sheet's today. */
764	    private static String record(String event, String sheetId, String user, Person person, LocalDate today) {
765	        return event + " sheet=" + sheetId + " by=" + user + " name=" + person.getName() + " grade="
766	                + person.gradeOn(today);
767	    }
768	
769	    /**
770	     * Save, refusing a name another user took on the sheet since it was checked, and an edit another
771	     * user saved over since the person was read.
772	     */
773	    private Person save(Person person) {
774	        try {
775	            return people.saveAndFlush(person);
776	        } catch (DataIntegrityViolationException e) {
777	            throw person.getContact() != null && String.valueOf(e.getMostSpecificCause().getMessage())
778	                    .toUpperCase().contains("PERSON_SHEET_CONTACT") ? contactInUse() : nameInUse();
779	        } catch (ObjectOptimisticLockingFailureException e) {
780	            throw stale();
781	        }
782	    }
783	
784	    /** The edit was made from a version of the person that another user has since saved over. */
785	    private static ResponseStatusException stale() {
786	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
787	                "Someone else has saved this person since it was opened.");
788	    }
789	
790	    private static ResponseStatusException contactInUse() {
791	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on this sheet.");
792	    }
793	
794	    private static ResponseStatusException nameInUse() {
795	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
796	    }
797	}
