1	package net.officefloor.hq.app.rollup;
2	
3	
4	/**
5	 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total
6	 * (the figures of their overdue claims that count, not capped), and the sheet's totals of each. A change takes a {@link #snapshot} before it alters anything
7	 * and calls {@link #recordChanges} after its own audit lines, which appends one ROLLUP line per
8	 * person whose figures moved (people in the order they were added; a new person counts as moved),
9	 * then a TOTALS line when any of the sheet's totals moved. A held person's OPEN claims count in none of
10	 * these (nor their PENDING ones), nor in a period's due-total; their SETTLED claims still do. So too a person whose
11	 * retirement date the sheet's today has reached. An overdue claim's figure has
12	 * its late charge added on top, and a live due is then never below the floor in force on its claim's date. A person's
13	 * due-total is at most the cap in force on the sheet's today, when there is one.
14	 */
15	@Service
16	public class RollupService {
17	
18	    /** A person's figures: claimed, due-total (null for n/a) and overdue-total. */
19	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
20	    }
21	
22	    /** The sheet's figures: each person's by id, in the order they were added. */
23	    public record Snapshot(Map<Long, Figures> people) {
24	
25	        public BigDecimal claimedTotal() {
26	            return people.values().stream().map(Figures::claimed).reduce(zero(), BigDecimal::add);
27	        }
28	
29	        /** People's due-totals added up (n/a is no figure), trimmed as {@link #trimmed} says. */
30	        public BigDecimal dueTotal() {
31	            return trimmed(people.values().stream().map(Figures::dueTotal).filter(Objects::nonNull).toList());
32	        }
33	
34	        /** People's overdue-totals added up, trimmed as {@link #trimmed} says. */
35	        public BigDecimal overdueTotal() {
36	            return trimmed(people.values().stream().map(Figures::overdueTotal).toList());
37	        }
38	
39	        /** The sum of people's figures, leaving out the single highest and lowest when there are three or more. */
40	        private static BigDecimal trimmed(List<BigDecimal> figures) {
41	            BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
42	            if (figures.size() < 3) {
43	                return sum;
44	            }
45	            return sum.subtract(figures.stream().reduce(BigDecimal::max).orElseThrow())
46	                    .subtract(figures.stream().reduce(BigDecimal::min).orElseThrow());
47	        }
48	    }
49	
50	    private final PersonRepository people;
51	    private final ClaimRepository claims;
52	    private final RateRepository rates;
53	    private final SheetRepository sheets;
54	    private final Audit audit;
55	
56	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
57	            Audit audit) {
58	        this.people = people;
59	        this.claims = claims;
60	        this.rates = rates;
61	        this.sheets = sheets;
62	        this.audit = audit;
63	    }
64	
65	    /** The sheet's figures as the store holds them now. */
66	    public Snapshot snapshot(String sheetId) {
67	        Sheet sheet = sheet(sheetId);
68	        LocalDate today = sheet.getToday();
69	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
70	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
71	        Map<Long, Figures> figures = new LinkedHashMap<>();
72	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
73	            BigDecimal claimed = zero();
74	            BigDecimal due = zero();
75	            BigDecimal overdue = zero();
76	            boolean anyFigure = false;
77	            for (Claim claim : sheetClaims) {
78	                if (!claim.getPersonId().equals(person.getId()) || !person.counts(claim, today)) {
79	                    continue;
80	                }
81	                claimed = claimed.add(claim.getAmount());
82	                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
83	                if (figure != null) {
84	                    anyFigure = true;
85	                    due = due.add(figure);
86	                    if (overdue(sheet, person, claim)) {
87	                        overdue = overdue.add(figure);
88	                    }
89	                }
90	            }
91	            // as on screen: n/a when the grade in force today has no rate today and no claim that
92	            // counts has a figure
93	            boolean none = inForce(sheetRates, person.gradeOn(today), today).isEmpty() && !anyFigure;
94	            figures.put(person.getId(), new Figures(person.getName(), claimed, none ? null : sheet.capped(due),
95	                    overdue));
96	        }
97	        return new Snapshot(figures);
98	    }
99	
100	    /**
101	     * Each person's due of their claims whose due-by falls in from..to (both inclusive) and that
102	     * counted by the status they had at the end of the to-day (as their status log records it; a
103	     * claim with none by then does not), by person id, for every person on the sheet (0.00 when
104	     * none). Each counts at its figure as shown now.
105	     */
106	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
107	        Sheet sheet = sheet(sheetId);
108	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
109	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
110	        Map<Long, BigDecimal> dues = new LinkedHashMap<>();
111	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
112	            BigDecimal due = zero();
113	            for (Claim claim : sheetClaims) {
114	                if (!claim.getPersonId().equals(person.getId()) || claim.getDueBy().isBefore(from)
115	                        || claim.getDueBy().isAfter(to) || !claim.statusAt(to)
116	                                .map(status -> person.counts(claim, status, sheet.getToday())).orElse(false)) {
117	                    continue;
118	                }
119	                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
120	                if (figure != null) {
121	                    due = due.add(figure);
122	                }
123	            }
124	            dues.put(person.getId(), due);
125	        }
126	        return dues;
127	    }
128	
129	    /** Record, once the change commits, the figures that moved since the snapshot taken before it. */
130	    public void recordChanges(String sheetId, String user, Snapshot before) {
131	        Snapshot after = snapshot(sheetId);
132	        String prefix = " sheet=" + sheetId + " by=" + user;
133	        boolean moved = false;
134	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
135	            Figures now = entry.getValue();
136	            Figures was = before.people().get(entry.getKey());
137	            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
138	                    && same(was.overdueTotal(), now.overdueTotal())) {
139	                continue;
140	            }
141	            moved = true;
142	            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + money(now.claimed())
143	                    + " due-total=" + money(now.dueTotal()) + " overdue-total=" + money(now.overdueTotal()));
144	        }
145	        if (moved && !(same(before.claimedTotal(), after.claimedTotal())
146	                && same(before.dueTotal(), after.dueTotal()) && same(before.overdueTotal(), after.overdueTotal()))) {
147	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + money(after.claimedTotal()) + " due-total="
148	                    + money(after.dueTotal()) + " overdue-total=" + money(after.overdueTotal()));
149	        }
150	    }
151	
152	    /**
153	     * A claim's figure as the screen shows it: the due fixed when settled, else the one bound by the
154	     * last statement (not while PENDING), else its live due (rounded as the claim rounds, see {@link Rounding}), with its late charge added on top, then raised to the floor (a correction's is not);
155	     * null when none.
156	     */
157	    private static BigDecimal figure(Sheet sheet, List<Rate> sheetRates, List<Claim> sheetClaims, Person person,
158	            Claim claim) {
159	        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
160	            return claim.getSettledDue();
161	        }
162	        BigDecimal figure = claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
163	                : inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
164	                        .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2,
165	                                Rounding.mode(sheet, Rounding.dateOf(claim, sheetClaims))))
166	                        .orElse(null);
167	        return LateCharge.withCharge(sheet, claim, person.gradeOn(claim.getDate()), figure);
168	    }
169	
170	    /**
171	     * Whether a claim is overdue on the sheet's today: OPEN or PENDING, not deferred, and past its due-by plus the
172	     * grace days of its person's grade on its date (see {@link Sheet#lateFrom}).
173	     */
174	    private static boolean overdue(Sheet sheet, Person person, Claim claim) {
175	        LocalDate today = sheet.getToday();
176	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null && claim.getDueBy() != null
177	                && sheet.lateFrom(claim.getDueBy(), claim.getDate(), person.gradeOn(claim.getDate())).isBefore(today);
178	    }
179	
180	    private Sheet sheet(String sheetId) {
181	        return sheets.findById(sheetId).orElseGet(() -> new Sheet(sheetId, null, null, LocalDate.now()));
182	    }
183	
184	    /** The grade's rate in force on a date, as {@link RateRepository#findInForce} picks it. */
185	    private static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
186	        return sheetRates.stream().filter(r -> r.getGrade().equals(grade))
187	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
188	                .max((a, b) -> a.getFromDate() == null ? -1 : b.getFromDate() == null ? 1
189	                        : a.getFromDate().compareTo(b.getFromDate()))
190	                .filter(r -> r.runsThrough(date));
191	    }
192	
193	    private static boolean same(BigDecimal a, BigDecimal b) {
194	        return a == null ? b == null : b != null && a.compareTo(b) == 0;
195	    }
196	
197	    private static BigDecimal zero() {
198	        return BigDecimal.ZERO.setScale(2);
199	    }
200	
201	    private static String money(BigDecimal value) {
202	        return value == null ? "n/a" : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
203	    }
