341	/**
342	 * The sheet's periods: added on the screen, each a name unique on the sheet (without regard to
343	 * case) and a from and to date, both inclusive; no two periods on a sheet overlap. A period can be
344	 * closed once: closing fixes its due-total at that moment, and no claim whose due-by is inside a
345	 * closed period can be added, edited, opened, settled or voided. A steward can reopen a closed period, which
346	 * makes its due-total live again. A period can instead be soft-closed: its figures are fixed in the
347	 * same way but its claims can still change; it can then be closed (fixing them afresh) or reopened. With grace days set, a change of the sheet's today closes the
348	 * periods past them (see {@link SheetService#setToday}).
349	 */
350	@Service
351	public class PeriodService {
352	
353	    private final PeriodRepository periods;
354	    private final SheetService sheets;
355	    private final SheetRepository sheetRows;
356	    private final Audit audit;
357	    private final RoleService roles;
358	
359	    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetRows, Audit audit,
360	            RoleService roles) {
361	        this.roles = roles;
362	        this.periods = periods;
363	        this.sheets = sheets;
364	        this.sheetRows = sheetRows;
365	        this.audit = audit;
366	    }
367	
368	    @Transactional(readOnly = true)
369	    public List<Period> list(String sheetId) {
370	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
371	    }
372	
373	    @Transactional
374	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
375	        roles.refuseViewer(sheetId, user);
376	        if (to.isBefore(from)) {
377	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's to-date cannot be before its from-date.");
378	        }
379	        sheets.load(sheetId, user);
380	        // hold the sheet so two periods added at the same moment are checked one after the other
381	        sheetRows.findLockedById(sheetId);
382	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
383	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
384	        }
385	        if (periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, to, from)) {
386	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
387	        }
388	        Period added;
389	        try {
390	            added = periods.saveAndFlush(new Period(sheetId, name, from, to));
391	        } catch (DataIntegrityViolationException e) {
392	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
393	        }
394	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName() + " from="
395	                + added.getFromDate() + " to=" + added.getToDate());
396	        return added;
397	    }
398	
399	    /**
400	     * Generate one period per calendar month from the from-date's month to the to-date's month, each
401	     * running from the first to the last day of its month and named yyyy-mm. A month whose name is
402	     * already a period, or whose days overlap a period on the sheet, is left out; the others are
403	     * still made. Refused (400) when the to-date is before the from-date.
404	     */
405	    @Transactional
406	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
407	        roles.refuseViewer(sheetId, user);
408	        if (to.isBefore(from)) {
409	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
410	        }
411	        sheets.load(sheetId, user);
412	        // hold the sheet so periods added at the same moment are checked one after the other
413	        sheetRows.findLockedById(sheetId);
414	        List<Period> made = new ArrayList<>();
415	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
416	            String name = month.toString();
417	            LocalDate first = month.atDay(1);
418	            LocalDate last = month.atEndOfMonth();
419	            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)
420	                    || periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, last, first)) {
421	                continue;
422	            }
423	            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
424	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
425	                    + " from=" + added.getFromDate() + " to=" + added.getToDate());
426	            made.add(added);
427	        }
428	        return made;
429	    }
430	
431	    /** Close a period, fixing its due-total now; refused (403) for a role the permission matrix does not allow and (409) when it is already closed. */
432	    @Transactional
433	    public Period close(String sheetId, String user, long id) {
434	        roles.refuseUnlessPermitted(sheetId, user, "close");
435	        // hold the sheet so no claim changes while the period's due-total is fixed
436	        sheetRows.findLockedById(sheetId)
437	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
438	        Period period = periods.findByIdAndSheetId(id, sheetId)
439	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
440	        if (period.isClosed()) {
441	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
442	        }
443	        return sheets.closePeriod(sheetId, user, period, false);
444	    }
445	
446	    /**
447	     * Soft-close a period, fixing its due-total and each person's now while claims dated inside it
448	     * can still change; refused (403) for a role the permission matrix does not allow to close and
449	     * (409) when it is already closed or soft-closed.
450	     */
451	    @Transactional
452	    public Period softClose(String sheetId, String user, long id) {
453	        roles.refuseUnlessPermitted(sheetId, user, "close");
454	        // hold the sheet so no claim changes while the period's due-total is fixed
455	        sheetRows.findLockedById(sheetId)
456	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
457	        Period period = periods.findByIdAndSheetId(id, sheetId)
458	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
459	        if (period.isClosed() || period.isSoftClosed()) {
460	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
461	        }
462	        return sheets.softClosePeriod(sheetId, user, period);
463	    }
464	
465	    /**
466	     * Reopen a closed or soft-closed period, making its due-total live again; refused (403) for a role the
467	     * permission matrix does not allow and (409) when the period is not closed.
468	     */
469	    @Transactional
470	    public Period reopen(String sheetId, String user, long id) {
471	        sheetRows.findLockedById(sheetId)
472	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
473	        Period period = periods.findByIdAndSheetId(id, sheetId)
474	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
475	        roles.refuseUnlessPermitted(sheetId, user, "reopen");
476	        if (!period.isClosed() && !period.isSoftClosed()) {
477	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed.");
478	        }
479	        period.reopen();
480	        Period saved = periods.saveAndFlush(period);
481	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
482	        return saved;
483	    }
484	
485	    /**
486	     * Refuse (423) a change to a claim due (by its due-by) inside a closed period. Holds the sheet first, so a
487	     * period cannot close while the change is under way.
488	     */
489	    public void refuseIfClosed(String sheetId, LocalDate date) {
490	        if (isClosed(sheetId, date)) {
491	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period.");
492	        }
493	    }
494	
495	    /**
496	     * Whether a claim due by this day lies inside a closed period. Holds the sheet first, so a
497	     * period cannot close while a change that relies on the answer is under way.
498	     */
499	    public boolean isClosed(String sheetId, LocalDate date) {
500	        sheetRows.findLockedById(sheetId);
501	        return periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date,
502	                date);
503	    }
504	
505	    /** Whether a claim due by this day lies inside a soft-closed period. */
506	    public boolean isSoftClosed(String sheetId, LocalDate date) {
507	        return periods.existsBySheetIdAndSoftClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId,
508	                date, date);
509	    }
510	}
