514	/**
515	 * Statements on a sheet. Taking a person's statement records their due-total at that moment, taken
516	 * on the sheet's today (held to the sheet's cap), or as of a date on or before it, and binds every claim of theirs that counts (OPEN, PENDING or SETTLED, but not a held
517	 * person's OPEN or PENDING claims) to the figure it has then; a claim of theirs that does not count is unbound,
518	 * so its figure is live again. The late charge is never bound: the due-total includes each claim's charge on the day, but a claim is
519	 * bound to the rate figure under it, not the floored one (the floor is applied last, see {@link net.officefloor.hq.app.claim.LateCharge}).
520	 * A steward can cancel a person's last statement: the claims it bound are live again (a figure bound
521	 * by a statement before it is not restored), and the statement before it is the last one again.
522	 */
523	@Service
524	public class StatementService {
525	
526	    /** A person's statements: how many, and the last one (none before the first). */
527	    public record Summary(long personId, int count, Statement last) {
528	    }
529	
530	    /** A statement just taken, with the person's claims as it left them. */
531	    public record Taken(Summary summary, List<Claim> claims) {
532	    }
533	
534	    /** A statement just cancelled: the person's statements left (none last when none are), and their claims. */
535	    public record Cancelled(Summary summary, List<Claim> claims) {
536	    }
537	
538	    private final StatementRepository statements;
539	    private final PersonRepository people;
540	    private final ClaimRepository claims;
541	    private final ClaimService claimService;
542	    private final RateRepository rates;
543	    private final RateLogRepository rateLog;
544	    private final SheetService sheets;
545	    private final Audit audit;
546	    private final RollupService rollup;
547	    private final RoleService roles;
548	
549	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
550	            ClaimService claimService, RateRepository rates, RateLogRepository rateLog, SheetService sheets, Audit audit, RollupService rollup,
551	            RoleService roles) {
552	        this.roles = roles;
553	        this.rollup = rollup;
554	        this.statements = statements;
555	        this.people = people;
556	        this.claims = claims;
557	        this.claimService = claimService;
558	        this.rates = rates;
559	        this.rateLog = rateLog;
560	        this.sheets = sheets;
561	        this.audit = audit;
562	    }
563	
564	    /** Each person's statements on the sheet who has taken any. */
565	    @Transactional(readOnly = true)
566	    public List<Summary> list(String sheetId) {
567	        Map<Long, Summary> by = new LinkedHashMap<>();
568	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
569	            Summary was = by.get(s.getPersonId());
570	            by.put(s.getPersonId(), new Summary(s.getPersonId(), was == null ? 1 : was.count() + 1, s));
571	        }
572	        return List.copyOf(by.values());
573	    }
574	
575	    /**
576	     * Take the person's statement now, or as of a date on or before the sheet's today (see
577	     * {@link #takeAsOf}). Refused (400) for a date after the sheet's today.
578	     */
579	    @Transactional
580	    public Taken take(String sheetId, String user, long personId, LocalDate asOf) {
581	        roles.refuseViewer(sheetId, user);
582	        Person person = people.lockByIdAndSheetId(personId, sheetId)
583	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
584	        LocalDate today = sheets.today(sheetId);
585	        if (asOf != null && asOf.isAfter(today)) {
586	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
587	                    "A statement cannot be taken as of a date after the sheet's today.");
588	        }
589	        if (asOf != null && !person.addedBy(asOf)) {
590	            throw new ResponseStatusException(HttpStatus.CONFLICT,
591	                    person.getName() + " was not on the sheet by " + asOf + ".");
592	        }
593	        RollupService.Snapshot before = rollup.snapshot(sheetId);
594	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
595	        Tally tally = asOf == null ? takeNow(sheetId, person, theirs, today) : takeAsOf(sheetId, person, theirs, asOf);
596	        claims.saveAllAndFlush(theirs);
597	        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, asOf != null ? asOf : today,
598	                tally.dueTotal(), tally.counted(), today));
599	        int count = (int) statements.findBySheetIdOrderByIdAsc(sheetId).stream()
600	                .filter(s -> Objects.equals(s.getPersonId(), personId)).count();
601	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
602	                + " due-total=" + money(tally.dueTotal()) + " claims=" + tally.counted()
603	                + (asOf != null ? " asof=" + asOf : ""));
604	        rollup.recordChanges(sheetId, user, before);
605	        return new Taken(new Summary(personId, count, taken), theirs);
606	    }
607	
608	    /** What a statement found: the person's due-total (none for n/a) and how many claims counted. */
609	    private record Tally(BigDecimal dueTotal, int counted) {
610	    }
611	
612	    /** Bind the person's claims that count now to their figures now. */
613	    private Tally takeNow(String sheetId, Person person, List<Claim> theirs, LocalDate today) {
614	        BigDecimal total = BigDecimal.ZERO.setScale(2);
615	        boolean anyFigure = false;
616	        int counted = 0;
617	        for (Claim claim : theirs) {
618	            if (person.counts(claim, today)) {
619	                BigDecimal figure = claimService.figure(sheetId, person, claim);
620	                BigDecimal charged = claimService.charged(sheetId, person, claim);
621	                claim.bind(true, figure);
622	                if (charged != null) {
623	                    total = total.add(charged);
624	                    anyFigure = true;
625	                }
626	                counted++;
627	            } else {
628	                claim.bind(false, null);
629	            }
630	        }
631	        // as on screen: n/a when the grade has no rate today and no claim that counts has a figure
632	        BigDecimal dueTotal = anyFigure || rates.findInForce(sheetId, person.gradeOn(today), today).isPresent() ? sheets.capped(sheetId, total) : null;
633	        return new Tally(dueTotal, counted);
634	    }
635	
636	    /**
637	     * Bind the person's claims that counted at the end of a day to their figures as they stood then:
638	     * every change made while the sheet's today was on or before the day counts, every later one
639	     * does not, and the day stands in for the sheet's today in every figure (the grade and rate in
640	     * force, the floor, late charges, holds, retirements, deferrals and the cap). A claim's status
641	     * then is the one its status log records; a claim with none by then did not count. A claim
642	     * bound by the last statement counts as bound then only when that statement was taken by then.
643	     * Every other claim of theirs is unbound.
644	     */
645	    private Tally takeAsOf(String sheetId, Person person, List<Claim> theirs, LocalDate day) {
646	        Sheet then = sheets.sheet(sheetId).asOf(day);
647	        List<Rate> ratesThen = rateLog.asOf(sheetId, day);
648	        boolean boundThen = statements.findBySheetIdOrderByIdAsc(sheetId).stream()
649	                .filter(s -> Objects.equals(s.getPersonId(), person.getId())).reduce((first, last) -> last)
650	                .map(last -> last.madeBy(day)).orElse(false);
651	        BigDecimal total = BigDecimal.ZERO.setScale(2);
652	        boolean anyFigure = false;
653	        int counted = 0;
654	        for (Claim claim : theirs) {
655	            ClaimStatus status = claim.statusAt(day).orElse(null);
656	            boolean stated = boundThen && claim.isStated();
657	            if (status == null || !person.countedAsOf(claim, status, day, stated)) {
658	                claim.bind(false, null);
659	                continue;
660	            }
661	            BigDecimal figure;
662	            BigDecimal charged;
663	            if (status == ClaimStatus.SETTLED) {
664	                figure = claim.settledDueAt(day);
665	                charged = figure;
666	            } else {
667	                figure = stated && status != ClaimStatus.PENDING ? claim.getStatedDue()
668	                        : RateRepository.inForce(ratesThen, person.gradeOn(claim.getDate(), day), claim.getDate())
669	                                .map(Rate::getPct)
670	                                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2,
671	                                        Rounding.mode(then, Rounding.dateOf(claim, theirs))))
672	                                .orElse(null);
673	                charged = LateCharge.withCharge(then, claim, person.gradeOn(claim.getDate(), day), figure,
674	                        status.isOpen() && !claim.isDeferredAsOf(status, day));
675	            }
676	            claim.bind(true, figure);
677	            if (charged != null) {
678	                total = total.add(charged);
679	                anyFigure = true;
680	            }
681	            counted++;
682	        }
683	        // as on screen: n/a when the grade then has no rate then and no claim that counted has a figure
684	        boolean none = !anyFigure && RateRepository.inForce(ratesThen, person.gradeOn(day, day), day).isEmpty();
685	        return new Tally(none ? null : then.capped(total), counted);
686	    }
687	
688	    /**
689	     * Cancel the person's last statement: each claim it bound is unbound, so its figure is live
690	     * again. Refused (403) to anyone but a steward, and (409) for a person with no statement.
691	     */
692	    @Transactional
693	    public Cancelled cancel(String sheetId, String user, long personId) {
694	        roles.refuseViewer(sheetId, user);
695	        roles.refuseUnlessSteward(sheetId, user);
696	        Person person = people.lockByIdAndSheetId(personId, sheetId)
697	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
698	        List<Statement> theirStatements = statements.findBySheetIdOrderByIdAsc(sheetId).stream()
699	                .filter(s -> Objects.equals(s.getPersonId(), personId)).toList();
700	        if (theirStatements.isEmpty()) {
701	            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " has no statement to cancel.");
702	        }
703	        Statement last = theirStatements.get(theirStatements.size() - 1);
704	        RollupService.Snapshot before = rollup.snapshot(sheetId);
705	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
706	        for (Claim claim : theirs) {
707	            if (claim.isStated()) {
708	                claim.bind(false, null);
709	            }
710	        }
711	        claims.saveAllAndFlush(theirs);
712	        statements.delete(last);
713	        statements.flush();
714	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
715	                + " due-total=" + money(last.getDueTotal()));
716	        rollup.recordChanges(sheetId, user, before);
717	        int count = theirStatements.size() - 1;
718	        return new Cancelled(new Summary(personId, count, count == 0 ? null : theirStatements.get(count - 1)), theirs);
719	    }
