4	/**
5	 * The as-of view. A screen showing the sheet as of a date sends it on every request in the
6	 * {@value #HEADER} header. Such a request that only reads is answered from the sheet as it stood at
7	 * the end of that date (see {@link SheetHistory}), its today the date, in a transaction that is then
8	 * rolled back, so nothing it does is kept or audited; any other is refused (423) and changes nothing.
9	 * Without the header a request is served as it is, and once a change has been made the sheet is kept
10	 * as it now stands (taking or releasing a claim editor's lock is no change to keep).
11	 */
12	@Component
13	public class AsOfFilter extends OncePerRequestFilter {
14	
15	    public static final String HEADER = "X-As-Of";
16	
17	    private static final String LOAD = "/api/sheets/load";
18	
19	    /** The requests that only read the sheet (with every path ending in {@code /list}). */
20	    private static final Set<String> READS = Set.of("/api/signin", LOAD, "/api/settings/get",
21	            "/api/people/watched", "/api/roles/delegations", "/api/claims/tags");
22	
23	    /** The changes that only take or release a claim editor's lock: not part of the sheet's history. */
24	    private static final Set<String> LOCKS = Set.of("/api/claims/lock", "/api/claims/unlock");
25	
26	    private final SheetHistory history;
27	    private final SheetService sheets;
28	    private final TransactionTemplate rolledBack;
29	    private final JsonMapper json;
30	
31	    public AsOfFilter(SheetHistory history, SheetService sheets, PlatformTransactionManager transactions,
32	            JsonMapper json) {
33	        this.history = history;
34	        this.sheets = sheets;
35	        this.rolledBack = new TransactionTemplate(transactions);
36	        this.json = json;
37	    }
38	
39	    @Override
40	    protected boolean shouldNotFilter(HttpServletRequest request) {
41	        return !"POST".equals(request.getMethod()) || !request.getRequestURI().startsWith("/api/");
42	    }
43	
44	    @Override
45	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
46	            throws ServletException, IOException {
47	        Body body = new Body(request);
48	        String path = request.getRequestURI();
49	        boolean read = READS.contains(path) || path.endsWith("/list");
50	        String sheet = body.sheet();
51	        String header = request.getHeader(HEADER);
52	        LocalDate asOf = null;
53	        if (header != null && !header.isBlank()) {
54	            try {
55	                asOf = LocalDate.parse(header.trim());
56	            } catch (DateTimeParseException e) {
57	                response.sendError(HttpStatus.BAD_REQUEST.value(), "Not a date: " + header);
58	                return;
59	            }
60	        }
61	        if (asOf == null) {
62	            chain.doFilter(body, response);
63	            if (sheet != null && path.equals(LOAD)) {
64	                history.captureFirst(sheet);
65	            } else if (sheet != null && !read && !LOCKS.contains(path)) {
66	                history.capture(sheet);
67	            }
68	            return;
69	        }
70	        if (!read) {
71	            response.sendError(HttpStatus.LOCKED.value(), "The sheet is shown as of a date and may not be changed.");
72	            return;
73	        }
74	        if (sheet == null) {
75	            chain.doFilter(body, response);
76	            return;
77	        }
78	        if (path.equals(LOAD)) {
79	            // a sheet never loaded starts as usual, and counts from the beginning of time
80	            String user = body.field("user");
81	            sheets.load(sheet, user == null || user.isBlank() ? "?" : user.trim());
82	            history.captureFirst(sheet);
83	        }
84	        LocalDate date = asOf;
85	        try {
86	            rolledBack.executeWithoutResult(status -> {
87	                status.setRollbackOnly();
88	                history.restore(sheet, date);
89	                try {
90	                    chain.doFilter(body, response);
91	                } catch (IOException | ServletException e) {
92	                    throw new IllegalStateException(e);
93	                }
94	            });
95	        } catch (IllegalStateException e) {
96	            if (e.getCause() instanceof IOException io) {
97	                throw io;
98	            }
99	            if (e.getCause() instanceof ServletException se) {
100	                throw se;
101	            }
102	            throw e;
103	        }
104	    }
105	
106	    /** The request with its body read once, so both this filter and the handler can read it. */
107	    private final class Body extends HttpServletRequestWrapper {
108	
109	        private final byte[] bytes;
110	        private JsonNode node;
111	
112	        Body(HttpServletRequest request) throws IOException {
113	            super(request);
114	            this.bytes = request.getInputStream().readAllBytes();
115	        }
116	
117	        /** The sheet the request is about: its {@code sheet}, or {@code id} for the sheet's own requests. */
118	        String sheet() {
119	            String sheet = field("sheet");
120	            if (sheet == null && getRequestURI().startsWith("/api/sheets/")) {
121	                sheet = field("id");
122	            }
123	            return sheet == null || sheet.isBlank() ? null : sheet.trim();
124	        }
125	
126	        String field(String name) {
127	            if (node == null) {
128	                try {
129	                    node = json.readTree(bytes);
130	                } catch (RuntimeException e) {
131	                    return null;
132	                }
133	            }
134	            JsonNode value = node == null ? null : node.get(name);
135	            return value == null || !value.isString() ? null : value.asString();
136	        }
137	
138	        @Override
139	        public ServletInputStream getInputStream() {
140	            ByteArrayInputStream in = new ByteArrayInputStream(bytes);
141	            return new ServletInputStream() {
142	                @Override
143	                public int read() {
144	                    return in.read();
145	                }
146	
147	                @Override
148	                public int read(byte[] b, int off, int len) {
149	                    return in.read(b, off, len);
150	                }
151	
152	                @Override
153	                public boolean isFinished() {
154	                    return in.available() == 0;
155	                }
156	
157	                @Override
158	                public boolean isReady() {
159	                    return true;
160	                }
161	
162	                @Override
163	                public void setReadListener(ReadListener listener) {
164	                    throw new UnsupportedOperationException();
165	                }
166	            };
167	        }
168	
169	        @Override
170	        public BufferedReader getReader() {
171	            return new BufferedReader(new InputStreamReader(getInputStream(), StandardCharsets.UTF_8));
172	        }
173	    }
174	}
175	package net.officefloor.hq.app.sheet;
176	
177	
178	/**
179	 * The sheet as it stood after each change, so it can be shown as of a date. After every change the
180	 * whole of the sheet's stored rows are kept (in {@code sheet_snapshot}) with the sheet's today then;
181	 * {@link #restore} puts the last one made on or before a date back in place of the sheet's rows,
182	 * its today the date, for the caller's transaction to read and then roll back.
183	 *
184	 * <p>The sheet's rows are found from the schema: every table with a {@code sheet_id}, and every
185	 * table without one that hangs off a person, claim or period of the sheet. A table added later is
186	 * so kept without change here.
187	 */
188	@Service
189	public class SheetHistory {
190	
191	    /** Tables never kept: the sheet row itself is kept apart, and the snapshots are the history. */
192	    private static final Set<String> SKIPPED = Set.of("SHEET", "SHEET_SNAPSHOT", "flyway_schema_history");
193	
194	    /** The tables others refer to, deleted last and put back first (in this order of putting back). */
195	    private static final List<String> PARENTS = List.of("PERSON", "PERIOD", "CLAIM");
196	
197	    /** A kept table: its name, the clause picking the sheet's rows (one parameter, the sheet's id) and its columns. */
198	    private record Table(String name, String where, List<String> columns) {
199	    }
200	
201	    private final JdbcTemplate jdbc;
202	    private volatile List<Table> tables;
203	    private volatile List<String> sheetColumns;
204	
205	    public SheetHistory(JdbcTemplate jdbc) {
206	        this.jdbc = jdbc;
207	    }
208	
209	    /** Keep the sheet as the store holds it now, made on its today; nothing when there is no such sheet. */
210	    @Transactional
211	    public void capture(String sheetId) {
212	        // hold the sheet so no change lands between reading its rows and its today
213	        List<LocalDate> today = jdbc.query("SELECT today FROM sheet WHERE id = ? FOR UPDATE",
214	                (rs, n) -> rs.getObject(1, LocalDate.class), sheetId);
215	        if (today.isEmpty()) {
216	            return;
217	        }
218	        save(sheetId, today.get(0));
219	    }
220	
221	    /** Keep the sheet as it is now as counting from the beginning of time, when nothing is kept for it yet. */
222	    @Transactional
223	    public void captureFirst(String sheetId) {
224	        if (jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, n) -> rs.getString(1), sheetId).isEmpty()) {
225	            return;
226	        }
227	        Long kept = jdbc.queryForObject("SELECT COUNT(*) FROM sheet_snapshot WHERE sheet_id = ?", Long.class, sheetId);
228	        if (kept == null || kept == 0) {
229	            save(sheetId, null);
230	        }
231	    }
232	
233	    /**
234	     * Within the caller's transaction, replace the sheet's rows by the last snapshot made on or
235	     * before {@code asOf} and set its today to {@code asOf}. The caller must roll back.
236	     */
237	    @Transactional
238	    public void restore(String sheetId, LocalDate asOf) {
239	        if (jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, n) -> rs.getString(1), sheetId).isEmpty()) {
240	            return;
241	        }
242	        List<byte[]> found = jdbc.query("SELECT data FROM sheet_snapshot WHERE sheet_id = ?"
243	                + " AND (made_on IS NULL OR made_on <= ?) ORDER BY seq DESC LIMIT 1",
244	                (rs, n) -> rs.getBytes(1), sheetId, asOf);
245	        Map<String, List<List<Object>>> data = found.isEmpty() ? Map.of() : read(found.get(0));
246	        List<Table> all = tables();
247	        for (int i = all.size() - 1; i >= 0; i--) {
248	            Table t = all.get(i);
249	            jdbc.update("DELETE FROM " + t.name() + " WHERE " + t.where(), sheetId);
250	        }
251	        for (Table t : all) {
252	            List<List<Object>> rows = data.get(t.name());
253	            if (rows == null || rows.isEmpty()) {
254	                continue;
255	            }
256	            List<String> columns = rows.get(0).stream().map(String::valueOf).toList();
257	            String sql = "INSERT INTO " + t.name() + " (" + String.join(", ", columns) + ") VALUES ("
258	                    + columns.stream().map(c -> "?").collect(Collectors.joining(", ")) + ")";
259	            for (List<Object> row : rows.subList(1, rows.size())) {
260	                jdbc.update(sql, row.toArray());
261	            }
262	        }
263	        List<List<Object>> sheet = data.get("SHEET");
264	        if (sheet != null && sheet.size() == 2) {
265	            List<String> columns = sheet.get(0).stream().map(String::valueOf).toList();
266	            List<Object> values = new ArrayList<>(sheet.get(1));
267	            values.add(sheetId);
268	            jdbc.update("UPDATE sheet SET " + columns.stream().map(c -> c + " = ?").collect(Collectors.joining(", "))
269	                    + " WHERE id = ?", values.toArray());
270	        }
271	        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", asOf, sheetId);
272	        // a claim editor's lock is this moment's, not the sheet's history: no editor is open as of a date
273	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ?", sheetId);
274	    }
275	
276	    /** Read the schema once the app is up, so the first change is not slowed by it. */
277	    @EventListener(ApplicationReadyEvent.class)
278	    public void warmUp() {
279	        tables();
280	        sheetColumns();
281	    }
282	
283	    private void save(String sheetId, LocalDate madeOn) {
284	        LinkedHashMap<String, List<List<Object>>> data = new LinkedHashMap<>();
285	        data.put("SHEET", rows("SELECT " + String.join(", ", sheetColumns()) + " FROM sheet WHERE id = ?", sheetId));
286	        for (Table t : tables()) {
287	            data.put(t.name(), rows("SELECT " + String.join(", ", t.columns()) + " FROM " + t.name() + " WHERE "
288	                    + t.where(), sheetId));
289	        }
290	        jdbc.update("INSERT INTO sheet_snapshot (sheet_id, made_on, data) VALUES (?, ?, ?)", sheetId, madeOn,
291	                write(data));
292	    }
293	
294	    /** The rows a query returns, the first the column names. */
295	    private List<List<Object>> rows(String sql, String sheetId) {
296	        return jdbc.query(sql, (ResultSet rs) -> {
297	            ResultSetMetaData meta = rs.getMetaData();
298	            List<List<Object>> rows = new ArrayList<>();
299	            List<Object> names = new ArrayList<>();
300	            for (int i = 1; i <= meta.getColumnCount(); i++) {
301	                names.add(meta.getColumnName(i));
302	            }
303	            rows.add(names);
304	            while (rs.next()) {
305	                List<Object> row = new ArrayList<>();
306	                for (int i = 1; i <= meta.getColumnCount(); i++) {
307	                    row.add(rs.getObject(i));
308	                }
309	                rows.add(row);
310	            }
311	            return rows;
312	        }, sheetId);
313	    }
314	
315	    /** The sheet's columns that can be set (all but its id and generated ones). */
316	    private List<String> sheetColumns() {
317	        if (sheetColumns == null) {
318	            sheetColumns = columns("SHEET").stream().filter(c -> !c.equals("ID")).toList();
319	        }
320	        return sheetColumns;
321	    }
322	
323	    /** The kept tables, those others refer to first. */
324	    private List<Table> tables() {
325	        if (tables != null) {
326	            return tables;
327	        }
328	        List<String> names = jdbc.queryForList("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES"
329	                + " WHERE TABLE_SCHEMA = 'PUBLIC' AND TABLE_TYPE = 'BASE TABLE' ORDER BY TABLE_NAME", String.class);
330	        List<Table> found = new ArrayList<>();
331	        for (String parent : PARENTS) {
332	            found.add(new Table(parent, "sheet_id = ?", columns(parent)));
333	        }
334	        for (String name : names) {
335	            if (SKIPPED.contains(name) || PARENTS.contains(name)) {
336	                continue;
337	            }
338	            List<String> columns = columns(name);
339	            String where = columns.contains("SHEET_ID") ? "sheet_id = ?"
340	                    : columns.contains("PERSON_ID") ? "person_id IN (SELECT id FROM person WHERE sheet_id = ?)"
341	                    : columns.contains("CLAIM_ID") ? "claim_id IN (SELECT id FROM claim WHERE sheet_id = ?)"
342	                    : columns.contains("PERIOD_ID") ? "period_id IN (SELECT id FROM period WHERE sheet_id = ?)"
343	                    : null;
344	            if (where != null) {
345	                found.add(new Table(name, where, columns));
346	            }
347	        }
348	        tables = List.copyOf(found);
349	        return tables;
350	    }
351	
352	    /** A table's columns that are stored (not generated), in order. */
353	    private List<String> columns(String table) {
354	        return jdbc.queryForList("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = 'PUBLIC'"
355	                + " AND TABLE_NAME = ? AND IS_GENERATED = 'NEVER' ORDER BY ORDINAL_POSITION", String.class, table);
356	    }
357	
358	    private static byte[] write(LinkedHashMap<String, List<List<Object>>> data) {
359	        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
360	        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
361	            out.writeObject(data);
362	        } catch (IOException e) {
363	            throw new UncheckedIOException(e);
364	        }
365	        return bytes.toByteArray();
366	    }
367	
368	    @SuppressWarnings("unchecked")
369	    private static Map<String, List<List<Object>>> read(byte[] data) {
370	        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(data))) {
371	            return (Map<String, List<List<Object>>>) in.readObject();
372	        } catch (IOException e) {
373	            throw new UncheckedIOException(e);
374	        } catch (ClassNotFoundException e) {
375	            throw new IllegalStateException(e);
376	        }
377	    }
378	}
379	package net.officefloor.hq.app.role;
380	
381	
382	/**
383	 * The roles a sheet assigns to user names: clerk (the default for any name), steward or viewer. A
384	 * steward can delegate the steward role to a user for a from-date to a to-date, inclusive: while
385	 * the sheet's today is inside it the user acts as a steward on the steward's behalf.
386	 */
387	@Service
388	public class RoleService {
389	
390	    private final RoleRepository roles;
391	    private final DelegationRepository delegations;
392	    private final SheetService sheets;
393	    private final Audit audit;
394	
395	    public RoleService(RoleRepository roles, DelegationRepository delegations, SheetService sheets, Audit audit) {
396	        this.roles = roles;
397	        this.delegations = delegations;
398	        this.sheets = sheets;
399	        this.audit = audit;
400	    }
401	
402	    @Transactional(readOnly = true)
403	    public List<Role> list(String sheetId) {
404	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
405	    }
406	
407	    /** The user's role on the sheet: clerk unless assigned otherwise; steward while a delegation to them is in force. */
408	    @Transactional(readOnly = true)
409	    public String roleOf(String sheetId, String user) {
410	        String assigned = assignedRoleOf(sheetId, user);
411	        return delegatorOf(sheetId, user).isPresent() ? Role.STEWARD : assigned;
412	    }
413	
414	    /** The role the sheet assigns the user, leaving aside any delegation. */
415	    private String assignedRoleOf(String sheetId, String user) {
416	        return roles.findBySheetIdAndUserName(sheetId, user).map(Role::getRole).orElse(Role.CLERK);
417	    }
418	
419	    /**
420	     * The steward the user acts for on the sheet's today: who made the latest delegation to them in
421	     * force then; none for a user who is a steward in their own right.
422	     */
423	    @Transactional(readOnly = true)
424	    public Optional<String> delegatorOf(String sheetId, String user) {
425	        if (Role.STEWARD.equals(assignedRoleOf(sheetId, user))) {
426	            return Optional.empty();
427	        }
428	        List<Delegation> theirs = delegations.findBySheetIdAndUserNameOrderByIdDesc(sheetId, user);
429	        if (theirs.isEmpty()) {
430	            return Optional.empty();
431	        }
432	        LocalDate today = sheets.today(sheetId);
433	        return theirs.stream().filter(d -> d.covers(today)).findFirst().map(Delegation::getSteward);
434	    }
435	
436	    @Transactional(readOnly = true)
437	    public List<Delegation> delegations(String sheetId) {
438	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
439	    }
440	
441	    /**
442	     * Delegate the steward role to a user from a from-date (none: the sheet's today) to a to-date,
443	     * inclusive. Refused (403) to anyone but a steward in their own right, and (400) for a to-date
444	     * before the from-date.
445	     */
446	    @Transactional
447	    public Delegation delegate(String sheetId, String user, String name, LocalDate from, LocalDate to) {
448	        sheets.refuseIfArchived(sheetId);
449	        sheets.load(sheetId, user);
450	        if (!Role.STEWARD.equals(assignedRoleOf(sheetId, user))) {
451	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can delegate the steward role.");
452	        }
453	        LocalDate fromDate = from != null ? from : sheets.today(sheetId);
454	        if (to.isBefore(fromDate)) {
455	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
456	        }
457	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, name, fromDate, to, user));
458	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + name + " from=" + fromDate
459	                + " to=" + to);
460	        return saved;
461	    }
462	
463	    /**
464	     * Refuse (403) an action the user's role may not take by the sheet's permission matrix (see
465	     * {@link net.officefloor.hq.app.sheet.Sheet#permits}).
466	     */
467	    // a refusal leaves the caller's transaction usable (a bulk action refuses one claim and goes on)
468	    @Transactional(readOnly = true, noRollbackFor = ResponseStatusException.class)
469	    public void refuseUnlessPermitted(String sheetId, String user, String action) {
470	        sheets.refuseIfArchived(sheetId);
471	        if (!sheets.sheet(sheetId).permits(action, roleOf(sheetId, user))) {
472	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " here.");
473	        }
474	    }
475	
476	    /**
477	     * Refuse (403) any change by a viewer: a viewer sees the sheet and may change nothing; and
478	     * (423) any change at all to an archived sheet.
479	     */
480	    // a refusal leaves the caller's transaction usable (a bulk action refuses one claim and goes on)
481	    @Transactional(readOnly = true, noRollbackFor = ResponseStatusException.class)
482	    public void refuseViewer(String sheetId, String user) {
483	        sheets.refuseIfArchived(sheetId);
484	        if (Role.VIEWER.equals(roleOf(sheetId, user))) {
485	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer may not change anything here.");
486	        }
487	    }
488	
489	    /** Refuse (403) anyone but a steward (in their own right or by a delegation in force). */
490	    @Transactional(readOnly = true)
491	    public void refuseUnlessSteward(String sheetId, String user) {
492	        if (!Role.STEWARD.equals(roleOf(sheetId, user))) {
493	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can do that.");
494	        }
495	    }
496	
497	    @Transactional
498	    public Role set(String sheetId, String user, String name, String role) {
499	        refuseViewer(sheetId, user);
500	        sheets.load(sheetId, user);
501	        Role assigned = roles.findBySheetIdAndUserName(sheetId, name).orElseGet(() -> new Role(sheetId, name, role));
502	        assigned.setRole(role);
503	        Role saved;
504	        try {
505	            saved = roles.saveAndFlush(assigned);
506	        } catch (DataIntegrityViolationException e) {
507	            // another user assigned this name a role at the same moment
508	            throw new ResponseStatusException(HttpStatus.CONFLICT, "This role was just set by someone else.");
509	        }
510	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role);
511	        return saved;
512	    }
513	}
