572	/**
573	 * The sheet's holidays: dates added on the screen, each at most once. A claim's due-by, fixed when
574	 * it is created, counts business days past them (see {@link #businessDaysAfter}). Adding a holiday
575	 * works out again the due-by of every claim on the sheet that is not SETTLED or VOID and is due by
576	 * it or later: from the claim's date, with the terms it was fixed with, over the holidays now on the
577	 * sheet; figures that move as a result are recorded after HOLIDAY_ADDED.
578	 */
579	@Service
580	public class HolidayService {
581	
582	    private final HolidayRepository holidays;
583	    private final SheetService sheets;
584	    private final SheetRepository sheetRows;
585	    private final Audit audit;
586	    private final RoleService roles;
587	    private final ClaimRepository claims;
588	    private final RollupService rollup;
589	
590	    public HolidayService(HolidayRepository holidays, SheetService sheets, SheetRepository sheetRows, Audit audit,
591	            RoleService roles, ClaimRepository claims, RollupService rollup) {
592	        this.claims = claims;
593	        this.rollup = rollup;
594	        this.holidays = holidays;
595	        this.sheets = sheets;
596	        this.sheetRows = sheetRows;
597	        this.audit = audit;
598	        this.roles = roles;
599	    }
600	
601	    @Transactional(readOnly = true)
602	    public List<Holiday> list(String sheetId) {
603	        return holidays.findBySheetIdOrderByDayAsc(sheetId);
604	    }
605	
606	    /** Add a holiday; a date already on the sheet's list is refused (409). */
607	    @Transactional
608	    public Holiday add(String sheetId, String user, LocalDate day) {
609	        roles.refuseViewer(sheetId, user);
610	        sheets.load(sheetId, user);
611	        // hold the sheet so the same date added twice at the same moment is checked one after the other
612	        sheetRows.findLockedById(sheetId);
613	        if (holidays.existsBySheetIdAndDay(sheetId, day)) {
614	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday.");
615	        }
616	        RollupService.Snapshot before = rollup.snapshot(sheetId);
617	        Holiday added;
618	        try {
619	            added = holidays.saveAndFlush(new Holiday(sheetId, day));
620	        } catch (DataIntegrityViolationException e) {
621	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday.");
622	        }
623	        Set<LocalDate> off = offDays(sheetId);
624	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
625	            if (claim.getStatus() != ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.VOID
626	                    && !claim.getDueBy().isBefore(day)) {
627	                claim.setDueBy(businessDaysAfter(off, claim.getDate(), claim.getTerms()));
628	            }
629	        }
630	        claims.flush();
631	        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + added.getDay());
632	        rollup.recordChanges(sheetId, user, before);
633	        return added;
634	    }
635	
636	    /**
637	     * The {@code days}-th business day after the date: counting forward from the day after it,
638	     * skipping every Saturday, Sunday and holiday on the sheet; the date itself when {@code days} is 0.
639	     */
640	    @Transactional(readOnly = true)
641	    public LocalDate businessDaysAfter(String sheetId, LocalDate date, int days) {
642	        return businessDaysAfter(offDays(sheetId), date, days);
643	    }
644	
645	    private Set<LocalDate> offDays(String sheetId) {
646	        return holidays.findBySheetIdOrderByDayAsc(sheetId).stream().map(Holiday::getDay)
647	                .collect(Collectors.toSet());
648	    }
649	
650	    /** The {@code days}-th day after the date that is no Saturday, Sunday or one of the holidays. */
651	    public static LocalDate businessDaysAfter(Set<LocalDate> holidays, LocalDate date, int days) {
652	        LocalDate d = date;
653	        for (int left = days; left > 0;) {
654	            d = d.plusDays(1);
655	            if (d.getDayOfWeek() != DayOfWeek.SATURDAY && d.getDayOfWeek() != DayOfWeek.SUNDAY
656	                    && !holidays.contains(d)) {
657	                left--;
658	            }
659	        }
660	        return d;
661	    }
662	}
