694	    }
695	
696	    @Transactional
697	    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, LocalDate toDate,
698	            BigDecimal pct) {
699	        roles.refuseViewer(sheetId, user);
700	        if (toDate != null && fromDate != null && toDate.isBefore(fromDate)) {
701	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A rate's to-date cannot be before its from-date.");
702	        }
703	        sheets.load(sheetId, user);
704	        RollupService.Snapshot before = rollup.snapshot(sheetId);
705	        Rate rate = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, fromDate)
706	                .orElseGet(() -> new Rate(sheetId, grade, fromDate, pct));
