718	                + saved.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
719	                + (fromDate != null ? " from=" + fromDate : "") + (toDate != null ? " to=" + toDate : ""));
720	        rollup.recordChanges(sheetId, user, before);
