727	public interface RateRepository extends JpaRepository<Rate, Long> {
728	
729	    /** A sheet's rates by grade, then by from-date. */
730	    List<Rate> findBySheetIdOrderByGradeAscFromDateAsc(String sheetId);
731	
732	    /** A grade's rates on a sheet. */
733	    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);
734	
735	    /** The grade's rate from a from-date, or its undated rate when the from-date is null. */
736	    default Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate fromDate) {
737	        return findBySheetIdAndGrade(sheetId, grade).stream()
738	                .filter(r -> Objects.equals(r.getFromDate(), fromDate)).findFirst();
739	    }
740	
741	    /**
742	     * The grade's rate in force on a date: the one with the latest from-date on or before it, an
743	     * undated rate counting as from the beginning of time; empty when none applies yet, or when that
744	     * one's to-date has passed by the date.
745	     */
746	    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
747	        return inForce(findBySheetIdAndGrade(sheetId, grade), grade, date);
748	    }
749	
750	    /** The grade's rate in force on a date among the given rates, as {@link #findInForce} picks it. */
751	    static Optional<Rate> inForce(List<Rate> rates, String grade, LocalDate date) {
752	        return rates.stream().filter(r -> r.getGrade().equals(grade))
753	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
754	                .max((a, b) -> a.getFromDate() == null ? -1 : b.getFromDate() == null ? 1
755	                        : a.getFromDate().compareTo(b.getFromDate()))
756	                .filter(r -> r.runsThrough(date));
757	    }
758	}
