760	
761	
762	/**
763	 * The paste box: lines of {@code name,amount,date,note}, each a DRAFT claim for the person of that
764	 * name (compared without regard to case), added in order. The date may be blank (the sheet's today)
765	 * and the note may be absent or hold commas. A note ending in {@code " #<reference>"} gives the claim
766	 * that external reference, which is not part of the note; a reference repeated within the paste, or
767	 * already used on the sheet, refuses the whole paste. Every line is held to exactly the claim form's rules;
768	 * the paste is one change, so a refused line adds nothing and writes nothing. Blank lines are
769	 * skipped; a paste with no lines is refused.
770	 */
771	@Service
772	public class ClaimPasteService {
773	
774	    /** The longest note the claim form takes. */
775	    private static final int NOTE_MAX = 1000;
776	
777	    /** The longest reference the claim form takes. */
778	    private static final int REF_MAX = 120;
779	
780	    private record Line(Person person, BigDecimal amount, LocalDate date, String note, String ref) {
781	    }
782	
783	    private final PersonRepository people;
784	    private final ClaimService claims;
785	    private final RoleService roles;
786	
787	    public ClaimPasteService(PersonRepository people, ClaimService claims, RoleService roles) {
788	        this.roles = roles;
789	        this.people = people;
790	        this.claims = claims;
791	    }
792	
793	    @Transactional
794	    public List<Claim> paste(String sheetId, String user, String text) {
795	        roles.refuseViewer(sheetId, user);
796	        List<Line> lines = new ArrayList<>();
797	        Set<String> refs = new HashSet<>();
798	        String[] raw = text.split("\\r?\\n|\\r");
799	        for (int i = 0; i < raw.length; i++) {
800	            if (!raw[i].isBlank()) {
801	                Line line = parse(sheetId, i + 1, raw[i]);
802	                if (line.ref() != null && !refs.add(line.ref().toLowerCase(Locale.ROOT))) {
803	                    throw refused("Line " + (i + 1) + ": the reference " + line.ref() + " is already in this paste.");
804	                }
805	                lines.add(line);
806	            }
807	        }
808	        if (lines.isEmpty()) {
809	            throw refused("Paste at least one line of name,amount,date,note.");
810	        }
811	        List<Claim> added = new ArrayList<>();
812	        for (Line line : lines) {
813	            added.add(claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(), null,
814	                    line.ref(), List.of()));
815	        }
816	        return added;
817	    }
818	
819	    private Line parse(String sheetId, int number, String text) {
820	        String[] fields = text.split(",", 4);
821	        if (fields.length < 2) {
822	            throw refused("Line " + number + " needs at least a name and an amount.");
823	        }
824	        String name = fields[0].trim();
825	        Person person = name.isEmpty() ? null : people.findBySheetIdAndNameIgnoreCase(sheetId, name).orElse(null);
826	        if (person == null) {
827	            throw refused("Line " + number + ": no one named \"" + name + "\" is on this sheet.");
828	        }
829	        String amount = fields[1].trim();
830	        if (!amount.matches(ClaimController.SIGNED_AMOUNT)) {
831	            throw refused("Line " + number + ": enter an amount with up to two decimals.");
832	        }
833	        LocalDate date = null;
834	        String dateText = fields.length > 2 ? fields[2].trim() : "";
835	        if (!dateText.isEmpty()) {
836	            try {
837	                date = LocalDate.parse(dateText);
838	            } catch (DateTimeParseException e) {
839	                throw refused("Line " + number + ": enter the date as YYYY-MM-DD, or leave it blank.");
840	            }
841	        }
842	        String note = fields.length > 3 ? fields[3].trim() : "";
843	        String ref = null;
844	        int hash = note.lastIndexOf(" #");
845	        if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
846	            ref = note.substring(hash + 2).trim();
847	            note = note.substring(0, hash).trim();
848	        }
849	        if (note.length() > NOTE_MAX) {
850	            throw refused("Line " + number + ": the note is too long.");
851	        }
852	        if (ref != null && ref.length() > REF_MAX) {
853	            throw refused("Line " + number + ": the reference is too long.");
854	        }
855	        return new Line(person, ClaimController.amount(amount), date, note, ref);
856	    }
857	
858	    private static ResponseStatusException refused(String reason) {
859	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
860	    }
861	}
