package net.officefloor.hq.app.holiday;


/**
 * The sheet's holidays: dates added on the screen, each at most once. A claim's due-by, fixed when
 * it is created, counts business days past them (see {@link #businessDaysAfter}). Adding a holiday
 * works out again the due-by of every claim on the sheet that is not SETTLED or VOID and is due by
 * it or later: from the claim's date, with the terms it was fixed with, over the holidays now on the
 * sheet; figures that move as a result are recorded after HOLIDAY_ADDED.
 */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final RoleService roles;
    private final ClaimRepository claims;
    private final RollupService rollup;

    public HolidayService(HolidayRepository holidays, SheetService sheets, SheetRepository sheetRows, Audit audit,
            RoleService roles, ClaimRepository claims, RollupService rollup) {
        this.claims = claims;
        this.rollup = rollup;
        this.holidays = holidays;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
        this.roles = roles;
    }

    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDayAsc(sheetId);
    }

    /** Add a holiday; a date already on the sheet's list is refused (409). */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate day) {
        roles.refuseViewer(sheetId, user);
        sheets.load(sheetId, user);
        // hold the sheet so the same date added twice at the same moment is checked one after the other
        sheetRows.findLockedById(sheetId);
        if (holidays.existsBySheetIdAndDay(sheetId, day)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Holiday added;
        try {
            added = holidays.saveAndFlush(new Holiday(sheetId, day));
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday.");
        }
        Set<LocalDate> off = offDays(sheetId);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus() != ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.VOID
                    && !claim.getDueBy().isBefore(day)) {
                claim.setDueBy(businessDaysAfter(off, claim.getDate(), claim.getTerms()));
            }
        }
        claims.flush();
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + added.getDay());
        rollup.recordChanges(sheetId, user, before);
        return added;
    }

    /**
     * The {@code days}-th business day after the date: counting forward from the day after it,
     * skipping every Saturday, Sunday and holiday on the sheet; the date itself when {@code days} is 0.
     */
    @Transactional(readOnly = true)
    public LocalDate businessDaysAfter(String sheetId, LocalDate date, int days) {
        return businessDaysAfter(offDays(sheetId), date, days);
    }

    private Set<LocalDate> offDays(String sheetId) {
        return holidays.findBySheetIdOrderByDayAsc(sheetId).stream().map(Holiday::getDay)
                .collect(Collectors.toSet());
    }

    /** The {@code days}-th day after the date that is no Saturday, Sunday or one of the holidays. */
    public static LocalDate businessDaysAfter(Set<LocalDate> holidays, LocalDate date, int days) {
        LocalDate d = date;
        for (int left = days; left > 0;) {
            d = d.plusDays(1);
            if (d.getDayOfWeek() != DayOfWeek.SATURDAY && d.getDayOfWeek() != DayOfWeek.SUNDAY
                    && !holidays.contains(d)) {
                left--;
            }
        }
        return d;
    }
}
package net.officefloor.hq.app.rate;


/**
 * The sheet's rates for each grade: set (or set again) on the screen, one per grade and from-date;
 * setting a grade's rate for a from-date it already has replaces that rate (and its to-date). A
 * to-date before the from-date is refused.
 */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateLogRepository rateLog;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final RoleService roles;

    public RateService(RateRepository rates, RateLogRepository rateLog, SheetService sheets, Audit audit,
            RollupService rollup, RoleService roles) {
        this.rateLog = rateLog;
        this.roles = roles;
        this.rollup = rollup;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, LocalDate toDate,
            BigDecimal pct) {
        roles.refuseViewer(sheetId, user);
        if (toDate != null && fromDate != null && toDate.isBefore(fromDate)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A rate's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, fromDate)
                .orElseGet(() -> new Rate(sheetId, grade, fromDate, pct));
        rate.setPct(pct);
        rate.setToDate(toDate);
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
        } catch (DataIntegrityViolationException e) {
            // another user set this grade's rate from this date at the same moment
            throw new ResponseStatusException(HttpStatus.CONFLICT, "This rate was just set by someone else.");
        }
        rateLog.saveAndFlush(new RateLog(saved, sheets.today(sheetId)));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade + " rate="
                + saved.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (fromDate != null ? " from=" + fromDate : "") + (toDate != null ? " to=" + toDate : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;


public interface RateRepository extends JpaRepository<Rate, Long> {

    /** A sheet's rates by grade, then by from-date. */
    List<Rate> findBySheetIdOrderByGradeAscFromDateAsc(String sheetId);

    /** A grade's rates on a sheet. */
    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    /** The grade's rate from a from-date, or its undated rate when the from-date is null. */
    default Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate fromDate) {
        return findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> Objects.equals(r.getFromDate(), fromDate)).findFirst();
    }

    /**
     * The grade's rate in force on a date: the one with the latest from-date on or before it, an
     * undated rate counting as from the beginning of time; empty when none applies yet, or when that
     * one's to-date has passed by the date.
     */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return inForce(findBySheetIdAndGrade(sheetId, grade), grade, date);
    }

    /** The grade's rate in force on a date among the given rates, as {@link #findInForce} picks it. */
    static Optional<Rate> inForce(List<Rate> rates, String grade, LocalDate date) {
        return rates.stream().filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max((a, b) -> a.getFromDate() == null ? -1 : b.getFromDate() == null ? 1
                        : a.getFromDate().compareTo(b.getFromDate()))
                .filter(r -> r.runsThrough(date));
    }
}
package net.officefloor.hq.app.claim;


/**
 * The paste box: lines of {@code name,amount,date,note}, each a DRAFT claim for the person of that
 * name (compared without regard to case), added in order. The date may be blank (the sheet's today)
 * and the note may be absent or hold commas. A note ending in {@code " #<reference>"} gives the claim
 * that external reference, which is not part of the note; a reference repeated within the paste, or
 * already used on the sheet, refuses the whole paste. Every line is held to exactly the claim form's rules;
 * the paste is one change, so a refused line adds nothing and writes nothing. Blank lines are
 * skipped; a paste with no lines is refused.
 */
@Service
public class ClaimPasteService {

    /** The longest note the claim form takes. */
    private static final int NOTE_MAX = 1000;

    /** The longest reference the claim form takes. */
    private static final int REF_MAX = 120;

    private record Line(Person person, BigDecimal amount, LocalDate date, String note, String ref) {
    }

    private final PersonRepository people;
    private final ClaimService claims;
    private final RoleService roles;

    public ClaimPasteService(PersonRepository people, ClaimService claims, RoleService roles) {
        this.roles = roles;
        this.people = people;
        this.claims = claims;
    }

    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        roles.refuseViewer(sheetId, user);
        List<Line> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        String[] raw = text.split("\\r?\\n|\\r");
        for (int i = 0; i < raw.length; i++) {
            if (!raw[i].isBlank()) {
                Line line = parse(sheetId, i + 1, raw[i]);
                if (line.ref() != null && !refs.add(line.ref().toLowerCase(Locale.ROOT))) {
                    throw refused("Line " + (i + 1) + ": the reference " + line.ref() + " is already in this paste.");
                }
                lines.add(line);
            }
        }
        if (lines.isEmpty()) {
            throw refused("Paste at least one line of name,amount,date,note.");
        }
        List<Claim> added = new ArrayList<>();
        for (Line line : lines) {
            added.add(claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(), null,
                    line.ref(), List.of()));
        }
        return added;
    }

    private Line parse(String sheetId, int number, String text) {
        String[] fields = text.split(",", 4);
        if (fields.length < 2) {
            throw refused("Line " + number + " needs at least a name and an amount.");
        }
        String name = fields[0].trim();
        Person person = name.isEmpty() ? null : people.findBySheetIdAndNameIgnoreCase(sheetId, name).orElse(null);
        if (person == null) {
            throw refused("Line " + number + ": no one named \"" + name + "\" is on this sheet.");
        }
        String amount = fields[1].trim();
        if (!amount.matches(ClaimController.SIGNED_AMOUNT)) {
            throw refused("Line " + number + ": enter an amount with up to two decimals.");
        }
        LocalDate date = null;
        String dateText = fields.length > 2 ? fields[2].trim() : "";
        if (!dateText.isEmpty()) {
            try {
                date = LocalDate.parse(dateText);
            } catch (DateTimeParseException e) {
                throw refused("Line " + number + ": enter the date as YYYY-MM-DD, or leave it blank.");
            }
        }
        String note = fields.length > 3 ? fields[3].trim() : "";
        String ref = null;
        int hash = note.lastIndexOf(" #");
        if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
            ref = note.substring(hash + 2).trim();
            note = note.substring(0, hash).trim();
        }
        if (note.length() > NOTE_MAX) {
            throw refused("Line " + number + ": the note is too long.");
        }
        if (ref != null && ref.length() > REF_MAX) {
            throw refused("Line " + number + ": the reference is too long.");
        }
        return new Line(person, ClaimController.amount(amount), date, note, ref);
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
    }
}
package net.officefloor.hq.app.quick;


/**
 * Quick-add: a DRAFT claim of an amount, dated the sheet's today with an empty note, for the person
 * of a name (compared without regard to case), adding the person with grade A first when the name is
 * not on the sheet. It is one change: a refused claim leaves no new person behind and writes nothing.
 */
@Service
public class QuickAddService {

    /** The grade a person added by quick-add takes. */
    private static final String GRADE = "A";

    public record Added(Person person, boolean created, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;
    private final RoleService roles;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService,
            RoleService roles) {
        this.roles = roles;
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        roles.refuseViewer(sheetId, user);
        Person existing = people.findBySheetIdAndNameIgnoreCase(sheetId, name).orElse(null);
        Person person = existing != null ? existing : personService.add(sheetId, user, name, GRADE, null);
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "", null, null, List.of());
        return new Added(person, existing == null, claim);
    }
}

