      const on = current.filter((p) => this.gradeToday(p) === grade);
      return {
        grade,
        count: on.length,
        dueTotal: money(on.reduce((sum, p) => sum + (this.dueOf(p) ?? 0), 0)),
        active: on.filter((p) => this.isActive(p)).length,
