231	          : countsFor(undefined, { ...c, status }, today));
232	      };
233	      out.push({ personId: c.personId, date: c.dueBy, cents: due, countsAt });
234	    }
235	    return out;
236	  });
237	  /** Each person's statements, by person id. */
238	  protected readonly statements = signal<ReadonlyMap<number, StatementSummary>>(new Map());
239	  /** Each person's patrons, in the order they were named. */
240	  protected readonly patrons = signal<PatronLink[]>([]);
241	  private readonly patronIdsByPerson = computed(() => {
242	    const by = new Map<number, number[]>();
243	    for (const l of this.patrons()) by.set(l.personId, [...(by.get(l.personId) ?? []), l.patronId]);
244	    return by;
245	  });
246	  /** The patron chosen on each person's row, by person id (the patron's id as text). */
247	  protected readonly patronChoices = signal<ReadonlyMap<number, string>>(new Map());
248	  /** The error of each person's last refused patron add, by person id. */
249	  protected readonly patronErrors = signal<ReadonlyMap<number, string>>(new Map());
250	  /** The ids of the people the signed-in user watches. */
251	  protected readonly watched = signal<ReadonlySet<number>>(new Set());
252	  /** The error of each person's last refused row action, by person id. */
253	  protected readonly rowErrors = signal<ReadonlyMap<number, string>>(new Map());
254	  /** Each grade's rate in force on the sheet's today. */
255	  protected readonly pctOf = computed(() => {
256	    const today = this.session.today();
257	    return new Map<string, string | undefined>(GRADES.map((g) => [g, pctOn(this.rates(), g, today)]));
258	  });
259	  /** The sheet's due-total: people's due-totals added up (skipping n/a), trimmed. */
260	  protected readonly dueTotal = computed(() =>
261	    money(trimmedSum(this.people().map((p) => this.dueOf(p)).filter((d): d is number => d !== null))),
262	  );
263	  /** The sheet's settled-total and open-total: everyone's added up, untrimmed, in whole cents. */
264	  protected readonly settledOpenTotals = computed(() => {
265	    const each = this.people().map((p) => this.settledOpenOf(p));
266	    return {
267	      settled: each.reduce((sum, t) => sum + t.settled, 0),
268	      open: each.reduce((sum, t) => sum + t.open, 0),
269	    };
270	  });
271	  protected readonly dueText = dueText;
272	  protected readonly money = money;
273	  /** The sheet's overdue claims that count: how many, and the sum of people's figures in whole cents, trimmed. */
274	  protected readonly overdueTotals = computed(() => {
275	    const each = this.people().map((p) => this.overdueOf(p));
276	    return {
277	      count: each.reduce((sum, o) => sum + o.count, 0),
278	      cents: trimmedSum(each.map((o) => o.cents)),
279	    };
280	  });
281	  /** Every tag ever used on the sheet, as the store held them when the sheet was loaded. */
282	  protected readonly usedTags = signal<string[]>([]);
283	  /**
284	   * Per tag ever used on the sheet (sorted): the figures of the claims that count which carry it,
285	   * in whole cents, untrimmed and without the cap; a claim with two tags counts in both.
286	   */
287	  protected readonly tagTotals = computed(() => {
288	    const totals = new Map<string, number>(this.usedTags().map((t) => [t, 0]));
289	    for (const c of this.claims()) for (const t of c.tags) if (!totals.has(t)) totals.set(t, 0);
290	    const today = this.session.today();
291	    for (const p of this.people()) {
292	      for (const c of this.claimsOf(p.id)) {
293	        if (c.tags.length === 0 || !countsFor(p, c, today)) continue;
294	        const figure = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c)) ?? 0;
295	        for (const t of c.tags) totals.set(t, (totals.get(t) ?? 0) + figure);
296	      }
297	    }
298	    return [...totals].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([tag, cents]) => ({ tag, cents }));
299	  });
300	  /**
301	   * Per calendar month (yyyy-mm, sorted) that any claim on the sheet is dated in: the figures of the
302	   * claims dated in it that count, in whole cents, untrimmed and without the cap.
303	   */
304	  protected readonly monthTotals = computed(() => {
305	    const totals = new Map<string, number>();
306	    for (const c of this.claims()) totals.set(c.date.slice(0, 7), 0);
307	    const today = this.session.today();
308	    for (const p of this.people()) {
309	      for (const c of this.claimsOf(p.id)) {
310	        if (!countsFor(p, c, today)) continue;
311	        const figure = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c)) ?? 0;
312	        const month = c.date.slice(0, 7);
313	        totals.set(month, (totals.get(month) ?? 0) + figure);
314	      }
315	    }
316	    return [...totals].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([month, cents]) => ({ month, cents }));
317	  });
318	  /** Per grade: the people not retired on it today, and their due-totals added up (skipping n/a). */
319	  protected readonly gradeSummary = computed<GradeSummary[]>(() => {
320	    const current = this.people().filter((p) => !p.retired);
321	    return GRADES.map((grade) => {
322	      const on = current.filter((p) => this.gradeToday(p) === grade);
323	      return {
324	        grade,
325	        count: on.length,
326	        dueTotal: money(on.reduce((sum, p) => sum + (this.dueOf(p) ?? 0), 0)),
327	        active: on.filter((p) => this.isActive(p)).length,
328	      };
329	    });
330	  });
331	  /** Per period: its due-total, as the periods list shows it. */
332	  protected readonly periodSummary = computed<PeriodSummary[]>(() =>
333	    this.periods().map((p) => ({ name: p.name, dueTotal: periodDueTotal(p, this.dues()) })),
334	  );
335	  /** A person's due-total for a period, as their row shows it. */
336	  protected periodDueOf(period: Period, personId: number): string {
337	    return personPeriodDueTotal(period, personId, this.dues());
338	  }
339	  /** Per status: how many of the sheet's claims have it, retired people's included. */
340	  protected readonly statusSummary = computed<StatusSummary[]>(() =>
341	    SUMMARY_STATUSES.map((status) => ({
342	      status,
343	      count: this.claims().filter((c) => c.status === status).length,
344	    })),
345	  );
346	  private readonly voidReasons = inject(VoidReasonList);
347	  /** Per reason on the sheet's void reasons: how many VOID claims were voided with it. */
348	  protected readonly voidReasonSummary = computed<VoidReasonSummary[]>(() =>
349	    this.voidReasons.list().map((r) => ({
350	      reason: r.reason,
351	      count: this.claims().filter((c) => c.status === 'VOID' && c.voidReason === r.reason).length,
352	    })),
353	  );
354	  protected readonly nameInput = signal('');
355	  protected readonly gradeInput = signal<string>('A');
356	  /** The date the form's grade is recorded from; blank for the sheet's today. */
357	  protected readonly gradeFromInput = signal('');
358	  /** The person's own terms in days; blank for none. */
359	  protected readonly termsInput = signal('');
360	  /** The person's contact; blank for none. */
361	  protected readonly contactInput = signal('');
362	  protected readonly editingId = signal<number | null>(null);
363	  /** The version of the person the editor was filled from. */
364	  private editingVersion = 0;
365	  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
366	  private submitting = false;
367	  protected readonly error = signal<string | null>(null);
368	  protected readonly quickName = signal('');
369	  protected readonly quickAmount = signal('');
370	  protected readonly quickError = signal<string | null>(null);
371	  /** Whether a quick-add is waiting for its answer: a second one meanwhile is ignored. */
372	  private quickSubmitting = false;
373	  protected readonly pasteText = signal('');
374	  /** How many claims the last paste added; cleared while the next one runs. */
375	  protected readonly pasteAdded = signal<number | null>(null);
376	  protected readonly pasteError = signal<string | null>(null);
377	  /** Whether a paste is waiting for its answer: a second one meanwhile is ignored. */
378	  private pasteSubmitting = false;
379	
380	  constructor() {
381	    // Re-read the sheet's people from the store every time a sheet is loaded.
382	    effect(() => {
383	      const sheet = this.session.sheet();
384	      this.session.loads();
385	      this.people.set([]);
386	      this.claims.set([]);
387	      this.usedTags.set([]);
388	      this.selectedClaims.set(new Set());
389	      this.bulkOpenResult.set(null);
390	      this.bulkOpenError.set(null);
391	      this.bulkSettleResult.set(null);
392	      this.bulkSettleError.set(null);
393	      this.bulkReassignTo.set('');
394	      this.bulkReassignResult.set(null);
395	      this.bulkReassignError.set(null);
396	      this.selectedPeople.set(new Set());
397	      this.bulkGradeInput.set('A');
398	      this.bulkGradeFrom.set('');
399	      this.bulkGraded.set(null);
400	      this.bulkGradeError.set(null);
401	      this.statements.set(new Map());
402	      this.rowErrors.set(new Map());
403	      this.patrons.set([]);
404	      this.patronChoices.set(new Map());
405	      this.patronErrors.set(new Map());
406	      this.watched.set(new Set());
407	      this.retireDates.set(new Map());
408	      this.holdFroms.set(new Map());
409	      this.statementAsOfs.set(new Map());
410	      this.holdTos.set(new Map());
411	      this.reset();
412	      this.quickName.set('');
413	      this.quickAmount.set('');
414	      this.quickError.set(null);
415	      this.pasteText.set('');
416	      this.pasteAdded.set(null);
417	      this.pasteError.set(null);
418	      if (sheet) {
419	        void this.fetch(sheet);
420	      }
421	    });
422	  }
423	
424	  private async fetch(sheet: string): Promise<void> {
425	    try {
426	      const [list, claims, statements, patrons, watched, tags] = await Promise.all([
427	        firstValueFrom(this.http.post<Person[]>('/api/people/list', { sheet })),
428	        firstValueFrom(this.http.post<Claim[]>('/api/claims/list', { sheet })),
429	        firstValueFrom(this.http.post<StatementSummary[]>('/api/statements/list', { sheet })),
430	        firstValueFrom(this.http.post<PatronLink[]>('/api/people/patrons/list', { sheet })),
431	        firstValueFrom(this.http.post<number[]>('/api/people/watched', { sheet, user: this.session.user() })),
432	        firstValueFrom(this.http.post<string[]>('/api/claims/tags', { sheet })),
433	      ]);
434	      if (this.session.sheet() === sheet) {
435	        this.claims.set(claims);
436	        this.usedTags.set(tags);
437	        this.statements.set(new Map(statements.map((s) => [s.personId, s])));
438	        this.patrons.set(patrons);
439	        this.watched.set(new Set(watched));
440	        this.people.set(list);
441	      }
442	    } catch {
443	      this.error.set('Could not read the people on this sheet.');
444	    }
445	  }
446	
447	  /** The person's grade in force on the sheet's today. */
448	  protected gradeToday(p: Person): string {
449	    return gradeOn(p.grades, this.session.today());
450	  }
451	
452	  /** The date a claim's live figures round by (see {@link roundingDate}). */
453	  private roundOn(c: Claim): string {
454	    return roundingDate(c, this.claimsOf(c.personId));
455	  }
456	
457	  protected claimsOf(personId: number): Claim[] {
458	    return this.claimsByPerson().get(personId) ?? [];
459	  }
460	
461	  protected claimedOf(personId: number): string {
462	    const p = this.peopleById().get(personId);
463	    return money(this.claimsOf(personId).reduce((sum, c) => sum + this.countedCents(p, c), 0));
464	  }
465	
466	  /** A claim's amount in whole cents when it counts toward the totals, else nothing. */
467	  private countedCents(p: Person | undefined, c: Claim): number {
468	    return countsFor(p, c, this.session.today()) ? cents(c.amount) : 0;
469	  }
470	
471	  /** What the person owes, in whole cents: the sum of their figures held to the sheet's cap. */
472	  protected dueOf(p: Person): number | null {
473	    const sum = this.figuresOf(p);
474	    const cap = this.capCents();
475	    return sum === null || cap === null ? sum : Math.min(sum, cap);
476	  }
477	
478	  /** How far the sum of the person's figures is above the cap, in whole cents; 0 otherwise. */
479	  protected excessOf(p: Person): number {
480	    const sum = this.figuresOf(p);
481	    const cap = this.capCents();
482	    return sum === null || cap === null ? 0 : Math.max(sum - cap, 0);
483	  }
484	
485	  /**
486	   * The sum of the figures of the person's claims that count, in whole cents. Null when their
487	   * grade in force on the sheet's today has no rate in force then, unless a claim that counts has
488	   * a figure.
489	   */
490	  private figuresOf(p: Person): number | null {
491	    const figures = this.claimsOf(p.id)
492	      .filter((c) => countsFor(p, c, this.session.today()))
493	      .map((c) => chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c)));
494	    if (this.pctOf().get(this.gradeToday(p)) === undefined && figures.every((f) => f === null)) return null;
495	    return figures.reduce<number>((sum, f) => sum + (f ?? 0), 0);
496	  }
497	
498	  /**
499	   * The figures of the person's claims that count, in whole cents, split into those of their
500	   * SETTLED claims and those of their OPEN and PENDING claims; together the sum before the cap.
501	   */
502	  protected settledOpenOf(p: Person): { settled: number; open: number } {
503	    const out = { settled: 0, open: 0 };
504	    for (const c of this.claimsOf(p.id)) {
505	      if (!countsFor(p, c, this.session.today())) continue;
506	      const figure = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c)) ?? 0;
507	      if (isOpen(c)) out.open += figure;
508	      else out.settled += figure;
509	    }
510	    return out;
511	  }
512	
513	  /**
514	   * Whether the person is active: they have an OPEN or PENDING claim that counts dated within the
515	   * 30 days up to and including the sheet's today.
516	   */
517	  protected isActive(p: Person): boolean {
518	    const today = this.session.today();
519	    if (!today) return false;
520	    const since = plusDays(today, -29);
521	    return this.claimsOf(p.id).some(
522	      (c) => isOpen(c) && countsFor(p, c, today) && c.date >= since && c.date <= today,
523	    );
524	  }
525	
526	  /**
527	   * The figures of the person's OPEN and PENDING claims that count, in whole cents, by age on the
528	   * sheet's today: 0 to 30 days (a claim dated after today included), 31 to 60, and 61 or more.
529	   */
530	  protected agedOf(p: Person): [number, number, number] {
531	    const today = this.session.today();
532	    const aged: [number, number, number] = [0, 0, 0];
533	    if (!today) return aged;
534	    for (const c of this.claimsOf(p.id)) {
535	      if (!isOpen(c) || !countsFor(p, c, today)) continue;
536	      const age = dayNumber(today) - dayNumber(c.date);
537	      const figure = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c)) ?? 0;
538	      aged[age <= 30 ? 0 : age <= 60 ? 1 : 2] += figure;
539	    }
540	    return aged;
541	  }
542	
543	  /** The person's overdue claims that count: how many, and the sum of their figures in whole cents. */
544	  protected overdueOf(p: Person): { count: number; cents: number } {
545	    const today = this.session.today();
546	    const late = this.claimsOf(p.id).filter((c) => countsFor(p, c, this.session.today())
547	      && overdue(c, today, graceOn(this.graces(), gradeOn(p.grades, c.date), c.date)));
548	    return {
549	      count: late.length,
550	      cents: late.reduce((sum, c) => sum + (chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c)) ?? 0), 0),
551	    };
552	  }
553	
554	  protected statementOf(personId: number): StatementSummary | undefined {
555	    return this.statements().get(personId);
556	  }
557	
558	  /** The person's patrons, by name, sorted, comma and space separated. */
559	  protected patronNamesOf(personId: number): string {
560	    return this.patronsOf(personId)
561	      .map((p) => p.name)
562	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
563	      .join(', ');
564	  }
565	
566	  /**
567	   * The person's backing in whole cents: their patrons' frozen figures over their SETTLED claims
568	   * dated within the 90 days up to and including the sheet's today.
569	   */
570	  protected backingOf(personId: number): number {
571	    const today = this.session.today();
572	    if (!today) return 0;
573	    const since = plusDays(today, -89);
574	    return this.patronsOf(personId)
575	      .flatMap((p) => this.claimsOf(p.id))
576	      .filter((c) => c.status === 'SETTLED' && c.date >= since && c.date <= today)
577	      .reduce((sum, c) => sum + (c.settledDue === null ? 0 : cents(c.settledDue)), 0);
578	  }
579	
580	  private patronsOf(personId: number): Person[] {
581	    const byId = this.peopleById();
582	    return (this.patronIdsByPerson().get(personId) ?? [])
583	      .map((id) => byId.get(id))
584	      .filter((p): p is Person => p !== undefined);
585	  }
586	
587	  protected setPatronChoice(id: number, value: string): void {
588	        this.contactInput.set(current.contact ?? '');
589	      }
590	    } catch {
591	      // the refusal is shown either way
592	    }
593	  }
594	}
595	
596	/**
597	 * A sheet total of people's figures: with three or more, the single highest and the single lowest
598	 * are left out.
599	 */
600	function trimmedSum(figures: readonly number[]): number {
601	  const sum = figures.reduce((s, f) => s + f, 0);
602	  return figures.length < 3 ? sum : sum - Math.max(...figures) - Math.min(...figures);
603	}
